-- Targeted TCF Reading distractor polish. 07_10: only 4 immutable banks, 2 questions per bank.
-- Original passages, stems, keys, weights, UI, prior versions, attempts and progress retained.
begin;
select pg_advisory_xact_lock(hashtext('tcf-reading-distractor-polish-20261119'));
create temp table cleanup_before on commit drop as
select (select count(*) from academy_tcf_reading.papers) as banks,
 (select count(*) from academy_tcf_reading.attempts) as attempts,
 (select md5(coalesce(string_agg(to_jsonb(a)::text,'' order by id),'')) from academy_tcf_reading.attempts a) as attempts_digest,
 (select md5(coalesce(string_agg(to_jsonb(p)::text,'' order by id,version),'')) from academy_tcf_reading.papers p) as banks_digest;
create temp table cleanup_other_pointers on commit drop as
select test_id,version from academy_tcf_reading.published_papers where test_id not in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10');
create temp table cleanup_scope(test_id text,changed integer[]) on commit drop;
insert into cleanup_scope values
('tcf-reading-07',array[35,38]::integer[]),
('tcf-reading-08',array[25,33]::integer[]),
('tcf-reading-09',array[29,35]::integer[]),
('tcf-reading-10',array[33,39]::integer[]);
do $preflight$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Expected 20 published reading papers'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id between 'tcf-reading-01' and 'tcf-reading-06' and version='tcf-reading-2026-11-close-reading-v6')<>6 then raise exception 'Tests 01-06 changed'; end if;
 
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10') and version='tcf-reading-2026-11-close-reading-v4')<>4 then raise exception 'Expected exactly 4 original v4 catalog pointers'; end if;
 if (select count(*) from academy_tcf_reading.papers where id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10') and version='tcf-reading-2026-11-distractor-polish-v5')<>0 then raise exception 'Target new versions already exist'; end if;
 if exists (select 1 from (values
('tcf-reading-07','ee5d04573673919ed8a1e99cde3b43c1'),
('tcf-reading-08','e2831943ff0af16d20b9fcb47b1290cc'),
('tcf-reading-09','d8c24c3d922a79ab93a765b6e2b2190d'),
('tcf-reading-10','e1b08c923a0ca4fb6df970c528e10a04')
) as expected(id,digest)
 join academy_tcf_reading.papers p on p.id=expected.id and p.version='tcf-reading-2026-11-close-reading-v4'
 where md5(p.content::text)<>expected.digest) then raise exception 'Published source bank digest changed since editorial inspection'; end if;
end $preflight$;
insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-07','tcf-reading-2026-11-distractor-polish-v5',$paper_7${"id":"tcf-reading-07","title":"TCF Reading · Test 07","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["L'ouverture de la poissonnerie","Le retrait de commandes payées","La livraison sans commande","L'achat libre sur tous les stands"],"passage":"Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord.\n\nPrésentez votre reçu au personnel chargé des retraits. Les stands alimentaires ne reprendront pas de vente après la fermeture annoncée.","question":"Quel service reste disponible après la fermeture ?","explanation":"Le passage indique : « Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord. » Cela justifie la réponse : Le retrait de commandes payées."},{"number":2,"points":3,"correct":"C","options":["De la levure","De la farine","Un saladier","Un four"],"passage":"Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies.\n\nLes participants travailleront par petits groupes. Un rangement collectif est prévu à la fin de la séance.","question":"Que doit apporter le participant ?","explanation":"Le passage indique : « Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies. » Cela justifie la réponse : Un saladier."},{"number":3,"points":3,"correct":"A","options":["Utiliser un contenant propre","Apporter un sac en papier","Acheter uniquement en espèces","Réserver une semaine avant"],"passage":"Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté.\n\nUn membre de l'équipe peut montrer comment remplir le récipient. Merci de laisser l'espace propre après votre passage.","question":"Quelle condition faut-il respecter ?","explanation":"Le passage indique : « Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté. » Cela justifie la réponse : Utiliser un contenant propre."},{"number":4,"points":3,"correct":"D","options":["À l'entrée de la salle","Le lendemain du repas","Après le dessert","Au moment de l'inscription"],"passage":"Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée.\n\nL'équipe préparera les quantités selon les demandes reçues. Elle ne pourra pas garantir un remplacement de plat au dernier moment.","question":"Quand faut-il signaler ce choix ?","explanation":"Le passage indique : « Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée. » Cela justifie la réponse : Au moment de l'inscription."},{"number":5,"points":9,"correct":"D","options":["La personne préparant la salade","Le nombre d'invités","Le jour du rendez-vous","Le lieu du repas"],"passage":"J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud.\n\nLes autres invités ont déjà été prévenus et garderont le même horaire. Nous mangerons autour de la grande table, puis pourrons sortir si le temps s'améliore.","question":"Qu'est-ce qui change dans le programme ?","explanation":"Le passage indique : « J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud. » Cela justifie la réponse : Le lieu du repas."},{"number":6,"points":9,"correct":"C","options":["Un restaurant réservé aux adhérents","Un cours obligatoire de jardinage","Des conseils pour préparer les légumes","Un remboursement de tous les achats"],"passage":"Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait.\n\nLes bénévoles indiquent également les quantités habituelles pour éviter de préparer trop de nourriture.","question":"Quelle aide accompagne le panier ?","explanation":"Le passage indique : « Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait. » Cela justifie la réponse : Des conseils pour préparer les légumes."},{"number":7,"points":9,"correct":"C","options":["Une place en terrasse","Un repas gratuit","Une table en salle","Une heure de départ libre"],"passage":"Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur.\n\nSi le temps reste agréable, vous pourrez demander une table extérieure à votre arrivée. Le personnel expliquera les disponibilités sans pouvoir les promettre à l'avance.","question":"Que garantit une réservation ?","explanation":"Le passage indique : « Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur. » Cela justifie la réponse : Une table en salle."},{"number":8,"points":9,"correct":"B","options":["Prévoir deux desserts par personne","Adapter la quantité aux personnes qui en mangeront","Conserver tout le gâteau pour le lendemain","Réduire le nombre d'invités"],"passage":"Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert.\n\nNous partagerons les autres plats sans changer le reste du repas ni demander un format plus grand.","question":"Pourquoi choisir ce format ?","explanation":"Le passage indique : « Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert. » Cela justifie la réponse : Adapter la quantité aux personnes qui en mangeront."},{"number":9,"points":9,"correct":"A","options":["Acheter une huile","Respecter l'heure du rendez-vous","S'inscrire à la dégustation","Goûter dans le lieu prévu"],"passage":"La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants.\n\nLes organisateurs présenteront l'origine des produits et quelques usages possibles. Le rendez-vous est destiné aux curieux comme aux clients habituels du magasin.","question":"Quelle obligation est absente ?","explanation":"Le passage indique : « La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants. » Cela justifie la réponse : Acheter une huile."},{"number":10,"points":9,"correct":"D","options":["Pour réserver les aliments aux commerçants","Pour interdire les dons gratuits","Pour privilégier les emballages décoratifs","Pour disposer d'informations vérifiables sur les produits"],"passage":"Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés.\n\nUne affiche rappelle les conditions d'accueil pour éviter que des aliments inutilisables soient déposés à côté du réfrigérateur.","question":"Pourquoi certains dépôts sont-ils exclus ?","explanation":"Le passage indique : « Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés. » Cela justifie la réponse : Pour disposer d'informations vérifiables sur les produits."},{"number":11,"points":15,"correct":"B","options":["Un choix toujours identique","La variation saisonnière du panier","Une livraison quotidienne obligatoire","L'absence de légumes locaux"],"passage":"Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis.\n\nLes adhérents choisissent un point de retrait et reçoivent les informations quelques jours avant la livraison. Une récolte abondante peut permettre un produit supplémentaire, tandis qu'un épisode de grêle oblige à revoir l'assortiment. Le producteur explique ces changements au lieu de remplacer systématiquement les légumes par des achats lointains. Le groupe souhaite conserver une relation claire entre ce qui pousse sur les terres et ce qui arrive dans les paniers.","question":"Quelle caractéristique faut-il accepter ?","explanation":"Le passage indique : « Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis. » Cela justifie la réponse : La variation saisonnière du panier."},{"number":12,"points":15,"correct":"A","options":["Une découverte progressive","Un changement de menu quotidien imposé","Une consommation forcée","La suppression de tout choix"],"passage":"Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion.\n\nLe personnel de cuisine observe les retours et recueille les remarques sans distribuer de note. Les enseignants peuvent préparer la découverte en parlant de l'origine du produit. L'équipe souhaite distinguer le refus d'un goût inconnu et celui d'une préparation particulière.","question":"Quelle approche est choisie ?","explanation":"Le passage indique : « Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion. » Cela justifie la réponse : Une découverte progressive."},{"number":13,"points":15,"correct":"A","options":["Une attention continue à la préparation","Le remplacement de la farine par de l'eau","L'absence de toute organisation","L'arrêt définitif des fournées"],"passage":"Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance.\n\nLe boulanger vérifie l'odeur, la texture et le temps écoulé avant de préparer la suite. Il ajuste certains gestes selon la température de l'atelier. Les apprentis découvrent qu'une recette écrite ne suffit pas toujours à décider du bon moment. Le responsable leur demande de noter leurs observations et de comparer plusieurs fournées. Il souhaite transmettre cette attention au processus, plutôt que promettre une méthode qui fonctionnerait de manière identique sans aucun contrôle des conditions réelles.","question":"Que nécessite cette méthode ?","explanation":"Le passage indique : « Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance. » Cela justifie la réponse : Une attention continue à la préparation."},{"number":14,"points":15,"correct":"C","options":["L'accès sans limite aux stocks des autres","La fermeture aux nouveaux producteurs","Le respect des créneaux et du nettoyage","La préparation simultanée sans réservation"],"passage":"Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage.\n\nLes réservations passent par un tableau commun et les produits restent dans des espaces identifiés. Le responsable présente les équipements à chaque nouveau groupe. Il souhaite éviter qu'un gain économique sur le local entraîne des difficultés de propreté ou de rangement. Les utilisateurs ont donc rédigé des règles simples après avoir essayé plusieurs organisations. Un bilan mensuel permettra de revoir les points qui posent problème sans attendre qu'une dispute entre deux entreprises bloque l'ensemble du fonctionnement de la cuisine.","question":"Quelle règle rend le partage possible ?","explanation":"Le passage indique : « Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage. » Cela justifie la réponse : Le respect des créneaux et du nettoyage."},{"number":15,"points":15,"correct":"A","options":["Les ingrédients peuvent changer","La cuisine refuse toute question","Les allergies disparaissent au restaurant","Les indications sont volontairement fausses"],"passage":"Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer.\n\nLes serveurs disposent d'une fiche commune, mais sont invités à demander confirmation lorsqu'une information manque. Le restaurant souhaite que les clients puissent exprimer leurs besoins sans recevoir une assurance improvisée. Les responsables expliquent aussi les limites liées au travail dans une même cuisine. Ils préfèrent donner une réponse précise, même si elle oblige à renoncer à un plat, plutôt que présenter le menu comme une garantie identique pour toutes les situations ou toutes les modifications demandées pendant le service.","question":"Pourquoi un échange reste-t-il nécessaire ?","explanation":"Le passage indique : « Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer. » Cela justifie la réponse : Les ingrédients peuvent changer."},{"number":16,"points":15,"correct":"C","options":["Éviter toute dégustation","Mémoriser le prix des serres","Reconnaître une diversité au sein d'un aliment","Choisir uniquement la plus grosse tomate"],"passage":"Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie.\n\nChaque groupe suit quelques plants et note leurs changements avant les récoltes. Une dégustation sera organisée lorsque les fruits seront mûrs. Les enseignants demandent aux enfants de décrire ce qu'ils observent avec leurs propres mots. Ils ne souhaitent pas désigner une variété gagnante une fois pour toutes : certaines conviennent mieux à une salade, d'autres à une sauce.","question":"Quel apprentissage est visé ?","explanation":"Le passage indique : « Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie. » Cela justifie la réponse : Reconnaître une diversité au sein d'un aliment."},{"number":17,"points":15,"correct":"C","options":["L'absence totale de matières premières","Le besoin d'importer tous les légumes","La perte de récoltes difficiles à écouler immédiatement","Le manque de magasins d'électroménager"],"passage":"Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard.\n\nLes volumes sont annoncés par les exploitants avant chaque tournée. L'équipe vérifie l'état des produits et choisit des recettes adaptées aux quantités disponibles. Les agriculteurs ne récupèrent donc pas nécessairement un produit identique à celui qu'ils ont apporté, mais une préparation qu'ils pourront conserver. Une étiquette indique l'origine et la composition. Le projet cherche à donner une valeur aux excédents, sans encourager volontairement une production inutile.","question":"Quel problème cette activité aide-t-elle à résoudre ?","explanation":"Le passage indique : « Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard. » Cela justifie la réponse : La perte de récoltes difficiles à écouler immédiatement."},{"number":18,"points":15,"correct":"D","options":["Masquer l'origine des produits","Utiliser tous les restes sans distinction","Supprimer les réfrigérateurs","Vérifier la sécurité des aliments"],"passage":"Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante.\n\nLes participants apportent des exemples de leur quotidien et discutent des délais au réfrigérateur. Les animateurs insistent sur l'importance de noter les dates et de refroidir correctement certaines préparations. Ils ne présentent pas toute transformation comme une manière d'effacer un défaut de conservation. Les recettes proposées restent simples, afin que les familles puissent les refaire avec leur équipement courant.","question":"Quelle précaution accompagne l'économie ?","explanation":"Le passage indique : « Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante. » Cela justifie la réponse : Vérifier la sécurité des aliments."},{"number":19,"points":15,"correct":"D","options":["Augmenter les pertes en cuisine","Supprimer tous les produits frais","Fermer plusieurs jours par semaine","Simplifier la gestion des approvisionnements"],"passage":"Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services.\n\nLes cuisiniers connaissent mieux les quantités préparées et peuvent utiliser certains ingrédients dans plusieurs recettes. Il suivra les ventes avant de modifier de nouveau la carte. L'objectif est de conserver une offre cohérente avec la taille de l'équipe, plutôt que d'afficher de nombreuses possibilités dont une partie serait souvent indisponible ou préparée sans le soin nécessaire.","question":"Quel objectif guide ce changement ?","explanation":"Le passage indique : « Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services. » Cela justifie la réponse : Simplifier la gestion des approvisionnements."},{"number":20,"points":21,"correct":"A","options":["Plus de prévisibilité contre moins de choix instantané","Un prix changeant après chaque livraison","Une suppression de toute relation avec les fermes","Des commandes sans engagement pour les producteurs"],"passage":"Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. Les volumes sont précisés avant la saison, avec les conditions de retrait et les possibilités d'absence. Les producteurs peuvent ainsi préparer certains investissements et les consommateurs comprendre les engagements pris. Le groupe accepte quelques variations liées à la récolte. Il préfère discuter ces aléas dans un cadre connu plutôt que découvrir une nouvelle condition à chaque commande.","question":"Quel compromis est décrit ?","explanation":"Le passage indique : « Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. » Cela justifie la réponse : Plus de prévisibilité contre moins de choix instantané."},{"number":21,"points":21,"correct":"B","options":["Les mêmes produits restent disponibles partout","Le menu suit davantage les saisons","Les clients doivent apporter tous leurs légumes","Le service devient uniquement estival"],"passage":"Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. Les clients retrouveront une indication sur les substitutions, afin de comprendre pourquoi une recette connue évolue. Le chef échange régulièrement avec plusieurs fournisseurs pour prévoir les quantités. Il ne promet pas que tout ingrédient pourra toujours venir du même périmètre. Il souhaite surtout que ses choix suivent une logique expliquée, plutôt que conserver à tout prix une carte identique sans regarder les conditions d'approvisionnement.","question":"Quelle conséquence le choix local a-t-il ?","explanation":"Le passage indique : « Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. » Cela justifie la réponse : Le menu suit davantage les saisons."},{"number":22,"points":21,"correct":"A","options":["L'aménagement pratique influence les usages","Les enfants refusent tous les verres","La fontaine est inutile","L'eau doit être payante pour être bue"],"passage":"Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. Les enfants hésitaient auparavant à demander un verre ou devaient quitter leur table pour le trouver. Le changement ne nécessitait pas une autre fontaine, mais une meilleure organisation du service. L'école vérifiera si cette facilité reste effective pendant les périodes d'affluence et si les plus petits peuvent se servir sans difficulté.","question":"Que suggère cette observation ?","explanation":"Le passage indique : « Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. » Cela justifie la réponse : L'aménagement pratique influence les usages."},{"number":23,"points":21,"correct":"D","options":["L'indépendance complète vis-à-vis du climat","Une quantité identique garantie chaque jour","La disparition du besoin de travail","L'incertitude inhérente à certaines productions"],"passage":"Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. Les visiteurs voient aussi les préparations et les tâches qui continuent lorsque la météo empêche de travailler dehors. Les agriculteurs expliquent leurs décisions et les possibilités de report. Ils souhaitent éviter qu'une journée agréable à la ferme donne l'image d'un métier toujours prévisible.","question":"Quelle idée la visite aide-t-elle à comprendre ?","explanation":"Le passage indique : « Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. » Cela justifie la réponse : L'incertitude inhérente à certaines productions."},{"number":24,"points":21,"correct":"C","options":["Démontrer l'inutilité de tous les outils","Réserver l'activité aux professionnels","Faciliter le réemploi des apprentissages à domicile","Augmenter le coût des recettes"],"passage":"Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. Les recettes sont choisies pour pouvoir être refaites dans une cuisine ordinaire, avec des quantités faciles à modifier. Les participants discutent de leurs propres contraintes : temps, place et nombre de convives. Le centre préfère une technique réellement réutilisée à une démonstration impressionnante mais impossible à reproduire.","question":"Pourquoi ce choix de matériel ?","explanation":"Le passage indique : « Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. » Cela justifie la réponse : Faciliter le réemploi des apprentissages à domicile."},{"number":25,"points":21,"correct":"D","options":["Un grand format reste économique quand le prix au kilo baisse, même si le foyer n'en utilise qu'une partie.","Les quantités consommées doivent remplacer le prix par kilo, qui n'apporte aucune information utile à la comparaison.","Le prix au kilo doit déterminer le classement initial; les pertes sont pertinentes uniquement après la décision d'achat.","Le prix unitaire aide à comparer, mais les pertes peuvent annuler le gain, pour les petits ménages."],"passage":"Une épicerie affiche le prix au kilo à côté des promotions. Cette information aide à comparer des formats différents, car le paquet le plus gros n'est pas toujours le plus économique. Le commerçant affiche la même unité pour chaque référence et explique où la lire. Les clients peuvent ainsi vérifier si une promotion correspond à leur besoin. Un grand paquet peut rester intéressant pour une famille nombreuse, mais devenir inutile pour une personne qui n'en consommera qu'une partie. Lors d'un essai, un lot familial affiche un prix unitaire inférieur mais entraîne des pertes chez les petits ménages. Le responsable conserve les deux informations côte à côte: coût par kilo et quantité que chacun pense réellement consommer.","question":"Pourquoi le responsable refuse-t-il de classer les offres à partir de la seule taille des emballages ?","explanation":"D associe prix au kilo et quantité réellement consommée. A suppose qu'un tarif unitaire bas reste rentable malgré les pertes; B écarte à tort le prix au kilo; C examine le gaspillage seulement après un classement qui peut ainsi être trompeur."},{"number":26,"points":21,"correct":"C","options":["Il privilégie le nombre de convives puis attribue la même portion aux groupes ayant des profils différents.","Il fixe les portions à partir des réservations et élimine la marge afin de réduire les restes.","Prévoir les portions selon les convives et leurs habitudes, tout en gardant une réserve pour les imprévus.","Il établit le volume de préparation à partir des portions servies lors du précédent événement de même taille."],"passage":"Un traiteur propose des portions modulables selon les convives. Il demande les effectifs définitifs deux jours avant le repas pour ajuster les achats. Les clients peuvent préciser les âges et les habitudes alimentaires de leurs invités. Le traiteur propose ensuite une estimation, sans présenter chaque personne comme une consommation identique. Une petite marge reste prévue pour les imprévus. Les organisateurs souhaitent réduire les restes sans risquer de manquer, et discutent aussi du rangement de ce qui pourrait être conservé après le repas. Deux événements comptant le même nombre d'invités ont récemment produit des besoins très différents parce que la répartition entre enfants et adultes n'était pas la même. Le traiteur ajuste donc le volume prévu, tout en gardant une réserve limitée.","question":"Quel raisonnement guide le calcul des portions du traiteur ?","explanation":"C croise effectif, habitudes et petite marge. A/D infèrent que deux événements de même taille se ressemblent; B supprime la réserve prévue."},{"number":27,"points":21,"correct":"B","options":["Classer les versions familiales selon leur ancienneté permettrait d'identifier celles qui ont conservé les pratiques considérées comme traditionnelles.","Documenter une tradition vivante sans hiérarchiser les variantes transmises entre les familles, selon leurs contextes respectifs.","Pour identifier les étapes où la transmission orale a transformé une recette initiale considérée comme stable.","Comparer les substitutions pourrait aider le comité à distinguer les variantes les plus proches d'une recette de référence."],"passage":"Un livre de recettes recueille les plats transmis dans plusieurs familles. Les variantes sont conservées : le comité ne cherche pas une version unique déclarée supérieure aux autres. Ces remarques accompagnent les recettes. Le livre ne cherche pas à séparer une version pure et des copies dégradées, mais à montrer comment une pratique se transmet entre personnes et se transforme avec leurs conditions de vie. Une famille a remplacé un ingrédient introuvable dans sa région d'accueil; une autre l'a conservé en changeant seulement la cuisson. Le comité publie les deux récits avec leur contexte au lieu d'en faire une succession d'erreurs par rapport à une version officielle.","question":"Pourquoi le comité conserve-t-il des récits différents d'un même plat ?","explanation":"B documente plusieurs manières de transmettre une pratique, sans hiérarchie d'authenticité. A et D imposent un classement par origine ou fidélité; C présuppose une recette initiale stable que le texte ne retient pas."},{"number":28,"points":21,"correct":"B","options":["Les différences de durée de pause montrent que les salariés n'expriment pas leurs préférences avec la même précision.","Des contraintes peuvent expliquer des pratiques différentes malgré des préférences déclarées semblables, dans les deux services étudiés.","La pause courte indique une préférence pour les préparations rapides que les salariés n'avaient pas déclarée.","Les deux services ont reçu des informations nutritionnelles différentes, ce qui explique leurs pratiques malgré les réponses."],"passage":"Une enquête sur les repas au travail mesure la durée disponible autant que les choix alimentaires. Certains salariés disent manger vite, non par préférence, mais à cause de pauses courtes. Les chercheurs regardent les horaires, la distance du lieu de restauration et les possibilités de conserver un repas. Les réponses aideront à choisir des améliorations concrètes, plutôt qu'à adresser uniquement des conseils généraux sans effet sur les conditions du déjeuner. Dans un service, les salariés expriment la même préférence pour un repas préparé que dans un autre, mais disposent de quinze minutes de pause au lieu de quarante-cinq. Le projet prévoit de comparer l'offre et les horaires avant d'interpréter leurs réponses comme de simples choix personnels.","question":"Quelle conclusion l'enquête peut-elle tirer de la différence entre les deux services ?","explanation":"B relie des comportements différents aux contraintes de temps malgré des goûts proches. A/C réinterprètent sans preuve les préférences; D suppose une différence de formation non mentionnée."},{"number":29,"points":21,"correct":"B","options":["À garantir la rotation des producteurs même lorsqu'un candidat démontre une activité déjà soutenable à long terme.","Tester les ventes et les capacités de fabrication avant de proposer au producteur un engagement plus durable.","À mesurer principalement la popularité immédiate du produit avant de décider du développement des capacités de production.","À retenir les candidats qui vendent le plus rapidement, indépendamment de leurs possibilités de fabrication ultérieures."],"passage":"Un marché prévoit un stand pour les petits producteurs débutants. Les emplacements tournent chaque mois pour leur permettre de tester la vente avant un engagement plus long. Les participants bénéficient d'un accompagnement pour présenter leurs prix et leurs produits. Ils peuvent ensuite comparer les retours des clients avec leurs capacités de production. Les candidats discuteront de ce qu'ils ont appris avant de décider d'une présence plus régulière. La rotation empêche un participant de monopoliser une place, mais elle ne constitue pas une promesse de clientèle. Un producteur qui reçoit de nombreux compliments peut encore décider de ne pas revenir si ses volumes de fabrication ne suivent pas.","question":"À quoi sert la période de présence limitée au marché ?","explanation":"B propose un essai évaluant retours et capacité de production. A fait de la rotation une fin permanente; C/D privilégient les ventes sans vérifier la soutenabilité."},{"number":30,"points":26,"correct":"C","options":["Deux assiettes portant la même mention ont une composition comparable, même si leurs portions individuelles peuvent varier.","La mention permet de conclure à un choix nutritionnel cohérent, mais ne renseigne pas sur la provenance des ingrédients.","La mention n'établit seule ni l'origine ni la composition du repas, dans les deux exemples présentés.","Les produits disponibles au moment de la préparation définissent l'équilibre du repas davantage que sa présentation."],"passage":"L'étiquette « fait maison » rassure certains clients, mais ne décrit pas à elle seule l'origine des produits ni l'équilibre d'un repas. Une diététicienne invite à poser plusieurs questions plutôt qu'à déduire toutes les qualités d'une seule mention. Elle propose notamment de regarder les quantités et les ingrédients effectivement servis. Le sens d'une mention doit rester précis, pour éviter qu'un seul mot remplace l'ensemble des informations nécessaires à un choix. Deux assiettes portent la même mention, mais l'une utilise une grande part de produits transformés et l'autre comporte davantage de légumes. La mention peut être exacte dans les deux cas, sans résoudre la question de l'équilibre nutritionnel ni celle de l'approvisionnement.","question":"Que montre la comparaison des deux assiettes portant la même mention ?","explanation":"C constate que la mention ne suffit à établir ni composition ni origine. A infère une composition similaire, B un équilibre nutritionnel non prouvé, D remplace l'analyse de composition par la disponibilité de produits."},{"number":31,"points":26,"correct":"D","options":["L'absence de détails sur la rémunération de l'un des fournisseurs explique directement la similitude des tarifs affichés.","Des tarifs proches indiquent généralement des coûts de production comparables, sauf lorsque les volumes vendus diffèrent.","Les achats groupés réduisent les frais fixes; l'autre fournisseur doit donc appliquer une marge plus faible pour s'aligner.","Des tarifs similaires ne garantissent pas des conditions de production identiques, même lorsque les produits proposés sont comparables."],"passage":"Un prix bas peut être obtenu par de grands volumes, une organisation efficace ou des conditions défavorables aux fournisseurs. Sans information sur ces facteurs, il serait imprudent d'attribuer la même cause à tous les produits bon marché. Des comparaisons entre produits proches et des informations sur les fournisseurs peuvent aider à comprendre ces différences. Le prix reste un repère important pour le budget, sans être une explication complète du fonctionnement de la production. Deux fournisseurs proposent un tarif similaire. L'un annonce un achat groupé avec de faibles frais fixes; pour l'autre, les conditions de rémunération ne sont pas documentées. L'acheteur ne peut déduire de l'égalité des prix une égalité des conditions de production.","question":"Quelle lecture des deux tarifs respecte le mieux les informations disponibles ?","explanation":"D refuse d'inférer les conditions de production à partir de prix similaires. A/B attribuent des causes sans documents, C calcule implicitement une marge non indiquée."},{"number":32,"points":26,"correct":"B","options":["L'adaptation locale fait perdre à la recette sa mémoire familiale, même si les gestes et les occasions restent proches.","Il conserve des usages transmis en adaptant la recette à un nouveau contexte, en préservant certaines pratiques familiales.","Une texture semblable suffit à considérer que les ingrédients essentiels ont été préservés lors de la transmission.","Le changement de céréale conserve surtout le nom du plat, mais les pratiques ne peuvent plus être rapprochées."],"passage":"Les recettes d'un patrimoine culinaire sont souvent adaptées aux produits accessibles dans le lieu où vivent les familles. Cette transformation n'efface pas nécessairement leur histoire. Elle peut être précisément la manière dont la transmission continue dans un contexte différent. Les familles racontent les substitutions qu'elles ont essayées et les goûts qu'elles souhaitaient retrouver. Ces récits montrent une continuité vivante, dont les changements peuvent être décrits plutôt que dissimulés sous l'idée d'une recette restée toujours identique. Pour une famille, changer de céréale a permis de retrouver la texture recherchée malgré l'absence du produit ancien. Le récit précise le changement au lieu de présenter la recette comme intacte; la parenté avec la pratique antérieure se lit aussi dans les gestes et les occasions de partage.","question":"Dans quel sens le changement d'ingrédient peut-il faire partie de la transmission ?","explanation":"B retient la continuité de repères pratiques malgré la substitution explicitée. A/D nient les usages conservés; C infère des ingrédients identiques de la seule texture."},{"number":33,"points":26,"correct":"A","options":["Une préférence initialement faible peut refléter la méconnaissance du plat plutôt qu'un rejet après dégustation.","La seconde note montre que les recettes nouvelles ont été modifiées entre les deux enquêtes, d'où leur meilleur accueil.","La hausse de la note moyenne montre que le plat nouveau sera apprécié de la même manière par tous les élèves.","Les dégustations neutralisent les habitudes antérieures, y compris pour les plats déjà connus des élèves."],"passage":"Une cantine veut améliorer ses menus à partir d'un vote. Les plats peu connus risquent d'obtenir peu de voix avant même d'avoir été goûtés. L'équipe ajoute des dégustations aux questionnaires pour éviter que la consultation ne reproduise seulement les habitudes existantes. L'équipe comparera leurs avis avant et après l'essai pour voir si le menu futur doit être ajusté ou simplement mieux présenté. Un plat nouveau reçoit peu de votes lors d'un premier sondage. Après dégustation, sa note moyenne augmente fortement, alors que celle des plats déjà connus varie peu. L'équipe distingue désormais la réaction à un nom de plat de l'appréciation après expérience.","question":"Que permet d'interpréter la seconde mesure des préférences ?","explanation":"A explique que le premier vote peut refléter la méconnaissance, car la note augmente après dégustation sans changement de recette annoncé. B invente une révision du plat; C généralise à tous les élèves et D prétend supprimer les habitudes pour toutes les recettes."},{"number":34,"points":26,"correct":"A","options":["Adapter les livraisons aux produits, au stockage et aux pertes constatées, ainsi qu'aux exigences des cuisines concernées.","Réduire le nombre de trajets permet d'évaluer le gain du dispositif, les pertes de cuisine appartenant au budget alimentaire.","Une cadence fixe pour chaque catégorie de produit rend les livraisons prévisibles et compense les contraintes de stockage.","Les commandes supplémentaires de produits fragiles peuvent être laissées au choix des restaurants, sans comptage des trajets."],"passage":"Un producteur remplace des livraisons quotidiennes par deux tournées hebdomadaires. Les trajets diminuent, mais certains restaurants doivent adapter leurs capacités de stockage. L'économie logistique suppose donc une coordination entre ceux qui livrent et ceux qui reçoivent. Le calendrier sera discuté à l'avance avec les cuisines. Certains produits nécessiteront un autre rythme, tandis que d'autres pourront être livrés ensemble sans difficulté. L'essai devra donc être évalué pour chaque type d'approvisionnement. Un restaurant peut conserver deux livraisons groupées de conserves mais doit encore recevoir certains produits fragiles plus souvent. La baisse globale des kilomètres parcourus ne serait pas une économie durable si les nouvelles contraintes provoquaient des pertes en cuisine.","question":"Quelle condition rend la réduction des tournées réellement pertinente ?","explanation":"A requiert une coordination des catégories, des stocks et des pertes. B/D retirent certains coûts du bilan, C applique une cadence unique malgré des contraintes différentes."},{"number":35,"points":26,"correct":"D","options":["Les deux cuisines ont prévenu une quantité comparable de surplus, puisque la masse envoyée au compost reste identique après les repas.","La seconde cuisine a valorisé une plus grande quantité de déchets organiques, car le compost représente une part plus importante de ses restes.","Les onze kilos de différence mesurent directement les aliments comestibles que la première cuisine aurait pu sauver en ajustant ses achats.","À nombre de repas égal, la seconde cuisine produit moins de surplus; le même tonnage de compost ne mesure donc pas la prévention."],"passage":"La lutte contre le gaspillage en cuisine est parfois réduite au recyclage des restes. Un collectif insiste d'abord sur les prévisions, les achats et les portions. Le traitement final reste utile, mais intervient après que des décisions évitables ont déjà produit un surplus. Ces informations peuvent conduire à modifier l'organisation du service avant même de chercher de nouvelles recettes pour transformer les aliments non consommés. Dans deux cuisines, la même quantité de déchets est compostée. La première produit beaucoup de restes et la seconde ajuste ses achats au nombre de repas, ce qui réduit la quantité jetée avant le compostage. Le collectif considère ces deux résultats comme distincts. Le bilan chiffré précise les mêmes cent repas préparés dans les deux cuisines. Dans la première, vingt-cinq kilos d'aliments non servis restent à la fin du service, dont dix sont compostés. Dans la seconde, les responsables ont revu les achats et les portions: quatorze kilos restent, dont dix sont également compostés. Les deux cuisines annoncent donc le même poids valorisé, mais la seconde a évité onze kilos de surplus en amont. L'équipe de mesure avertit que les restes ne sont pas tous comestibles et qu'une comparaison entre services devrait distinguer les épluchures des aliments préparés non servis. Le comité veut publier des indicateurs séparés: masse de surplus pour cent repas, nature des restes et part finalement valorisée. Il refuse un classement fondé sur le seul tonnage du compost, tout comme un calcul qui considérerait tous les déchets résiduels comme évitables.","question":"Quelle comparaison le bilan permet-il de soutenir sans assimiler prévention et valorisation ?","explanation":"D compare les surplus de 25 et 14 kg pour cent repas sans confondre prévention et compostage, identique à 10 kg. A déduit la prévention du seul compost, B confond proportion de restes et quantité valorisée, C traite sans preuve les onze kilos de différence comme entièrement comestibles."},{"number":36,"points":33,"correct":"B","options":["Le nombre de commandes communes a diminué après une modification du choix disponible au moment de la réservation.","Réduire trajets et emballages superflus tout en conservant les adaptations nécessaires aux contraintes alimentaires personnelles des foyers.","La préférence pour les paniers différents explique à elle seule la totalité des trajets et des emballages.","Les paniers communs rendent les commandes plus efficaces en empêchant toute prise en compte des contraintes alimentaires."],"passage":"Un service de paniers « personnalisés » promet de répondre à chaque préférence. Pour y parvenir, il multiplie les petites commandes et les emballages séparés. Les clients gagnent en choix, mais le système perd une partie de l'efficacité du panier commun. La personnalisation peut déplacer les coûts matériels vers l'organisation qui la rend possible. Pour préserver une partie de cette souplesse, le service propose désormais quelques choix communs plutôt qu'une composition entièrement différente pour chaque foyer. Les clients peuvent indiquer des contraintes essentielles, mais toutes les préférences ne donneront plus lieu à un emballage séparé. Le responsable souhaite mesurer les volumes réellement transportés et jetés, pas seulement la satisfaction au moment de la commande. Il espère ainsi conserver un service utile, tout en rendant visibles les ressources mobilisées derrière une offre qui semblait simplement apporter davantage de liberté à chacun. Le responsable compare deux mois: le nombre de clients reste stable, mais les petites commandes individualisées multiplient les trajets et les cartons. Une formule intermédiaire supprime certaines variantes sans toucher aux contraintes alimentaires que les clients jugent indispensables.","question":"Que cherche principalement à corriger la formule intermédiaire ?","explanation":"B réduit les ressources mobilisées par des choix individualisés tout en conservant les contraintes essentielles. A ajoute une évolution des commandes non constatée; C attribue tous les coûts aux préférences sans les autres facteurs; D nie les adaptations conservées."},{"number":37,"points":33,"correct":"B","options":["Elle privilégie les produits de saison mais laisse les exceptions hors du menu pour garder un message simple.","Elle explique la priorité locale et les exceptions, rendant les choix vérifiables, au lieu d'une promesse générale.","Elle établit qu'un fournisseur local peut remplacer tous les ingrédients même lorsque certaines épices ne sont pas régionales.","Elle publie la provenance des légumes sans préciser les raisons du choix des ingrédients venus d'ailleurs."],"passage":"Un restaurant annonce une cuisine locale. Son menu comporte surtout des produits de proximité, mais certains ingrédients complémentaires viennent d'ailleurs. Le chef publie ces exceptions et leurs raisons. La cohérence de son engagement repose sur des choix expliqués, plutôt que sur une formule absolue que la pratique démentirait. Il indique les fournisseurs principaux et la période à laquelle certains produits deviennent disponibles. Les clients peuvent ainsi comprendre pourquoi une recette change ou pourquoi une épice n'est pas produite dans la région. Le restaurateur souhaite éviter qu'une promesse trop générale transforme chaque exception en soupçon de tromperie. Cette précision n'empêche pas la discussion sur ses choix. Elle permet au contraire de les comparer avec d'autres possibilités, en distinguant une priorité réelle d'une affirmation commerciale qui paraîtrait valable pour chaque ingrédient et pendant toute l'année. Sur un menu, le chef indique qu'une épice vient de loin alors que les légumes sont achetés dans la région selon la saison. Un autre établissement affiche simplement « 100 % local » sans préciser ses achats. Les clients ne peuvent pas vérifier les mêmes choses à partir des deux annonces.","question":"En quoi la démarche du premier chef rend-elle son engagement plus crédible ?","explanation":"B rend la promesse locale vérifiable en précisant sa portée et ses exceptions. A et D omettent des explications importantes; C transforme une priorité locale en approvisionnement intégral alors que des exceptions subsistent."},{"number":38,"points":33,"correct":"C","options":["Les deux groupes comprennent la brochure; les écarts de pratiques reflètent donc principalement la motivation des participants aux ateliers.","L'ouverture plus tardive du point de vente explique le changement observé, tandis que l'effet propre de l'atelier reste secondaire.","Le second dispositif accompagne une évolution des pratiques, mais l'accès aux produits et les situations initiales empêchent d'en isoler l'effet.","Les différences initiales entre quartiers rendent la comparaison finale inutilisable, même pour décrire l'évolution des repas déclarés par les participants."],"passage":"Une ville distribue des brochures pour encourager une alimentation variée. Une enquête montre cependant que plusieurs ménages disposent d'un équipement de cuisson limité et de peu de commerces accessibles. La connaissance des recommandations n'est pas leur principale difficulté. Des conseils utiles doivent s'accompagner d'une attention aux conditions concrètes qui permettent de les suivre. Les associations proposent de compléter la campagne par des ateliers utilisant le matériel réellement disponible dans les logements. Elles demandent aussi que l'accès aux commerces et aux lieux de conservation soit examiné. Certaines personnes connaissent déjà les conseils et souhaitent les suivre, mais doivent composer avec un budget ou un horaire peu compatible avec l'offre locale. Les responsables veulent donc éviter un message qui ferait de ces contraintes une faute personnelle. La réussite du programme dépendra de ce qu'il rend effectivement possible dans le quotidien des familles auxquelles il s'adresse. Deux ménages connaissent les mêmes recommandations. Le premier dispose d'une cuisine équipée et de commerces proches; le second ne peut conserver certains aliments ni se déplacer aux heures d'ouverture. Répéter la brochure ne modifierait pas ces différences concrètes. Une seconde enquête suit des familles après deux ateliers. Dans le premier quartier, les participants reçoivent la brochure et savent expliquer les recommandations, mais plusieurs déclarent encore renoncer aux légumes frais faute de conservation adaptée. Dans le second, un atelier de cuisine avec le matériel réellement disponible est associé à une ouverture plus tardive du point de vente. Les participants de ce quartier décrivent davantage de repas préparés selon les conseils. Les organisateurs observent cependant que les deux groupes différaient déjà par leur équipement et leur proximité des commerces. Ils ne présentent donc pas l'écart comme une preuve de l'effet exclusif de l'atelier. Pour la suite, ils prévoient de mesurer séparément compréhension des conseils, accès concret aux produits et changements observés dans les pratiques, afin que le succès d'une brochure ne soit pas confondu avec son application.","question":"Quelle interprétation des deux quartiers respecte à la fois le résultat observé et ses limites ?","explanation":"C constate l'évolution des pratiques dans le second quartier sans isoler l'effet de l'atelier, de l'accès commercial ou des conditions initiales. A attribue sans mesure l'écart à la motivation, B fait de l'ouverture tardive la cause principale non isolée, D rejette à tort toute utilité descriptive de la comparaison."},{"number":39,"points":33,"correct":"D","options":["Chaque diminution de poids ouvre droit à un ajustement monétaire, tandis que l'information sur les récoltes relève du libre choix du producteur.","La ferme doit décrire les soins apportés, mais la variabilité des récoltes rend l'information saisonnière facultative.","Le risque accepté par les membres écarte tout remboursement, même quand les engagements du producteur ne sont pas tenus.","L'aléa climatique peut modifier la quantité reçue sans remboursement automatique, mais la ferme demeure tenue aux soins et informations prévus."],"passage":"Une ferme propose aux clients de partager les risques d'une saison en payant un panier à l'avance. Certains craignent de recevoir moins lors d'une mauvaise récolte. Le producteur explique que le contrat n'est pas une garantie de volume identique, mais une relation différente avec l'activité agricole. Le prix finance aussi une continuité de production confrontée à l'incertitude. Le groupe prévoit une visite des cultures et une information régulière sur l'évolution de la saison. Les membres pourront discuter des substitutions possibles, tout en comprenant qu'un engagement ne fait pas disparaître les aléas du climat. Le producteur garde la responsabilité d'expliquer ses choix et de travailler avec soin. Les acheteurs, eux, acceptent que leur contribution ne corresponde pas toujours au même poids de produits. L'année suivante, deux membres ayant payé le même montant reçoivent des volumes différents selon les récoltes des parcelles concernées. Le contrat précise les modalités d'information et les choix de remplacement, mais ne promet pas d'ajuster rétroactivement chaque contribution au poids reçu. Au terme d'une autre saison, la ferme a connu une baisse de rendement sur certaines parcelles malgré les soins documentés. Les membres avaient réglé des contributions identiques, mais leurs paniers, répartis selon les parcelles et les produits disponibles, ont varié en poids. Le contrat prévoit une réunion pour expliquer les aléas, un remplacement possible par d'autres légumes et un remboursement seulement si la ferme n'a pas assuré les engagements de production et d'information précisés au départ. Il n'introduit aucune régularisation automatique au kilogramme manquant. Un membre estime que toute variation de poids prouve un défaut de service; un autre fait remarquer que l'acceptation du risque climatique ne retire pas au producteur ses obligations de diligence et de transparence. Les deux conviennent que la description des récoltes et des substitutions doit pouvoir être vérifiée, même lorsque le montant versé n'est pas recalculé.","question":"Quelle interprétation distingue correctement le risque partagé des obligations que le producteur conserve ?","explanation":"D distingue un aléa de rendement accepté par les membres et des obligations contractuelles toujours vérifiables. A introduit un remboursement au poids exclu; B rend facultative l'information; C nierait même le remboursement prévu en cas de manquement."}]}$paper_7$::jsonb),
('tcf-reading-08','tcf-reading-2026-11-distractor-polish-v5',$paper_8${"id":"tcf-reading-08","title":"TCF Reading · Test 08","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Dix-neuf heures trente","Dix-neuf heures quinze","Dix-huit heures quarante-cinq","Vingt heures"],"passage":"La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires.\n\nMerci de prévoir le temps nécessaire avant la fermeture des vestiaires. Le personnel rappellera cette règle à l'entrée de chaque séance.","question":"Jusqu'à quand peut-on se changer ?","explanation":"Le passage indique : « La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires. » Cela justifie la réponse : Dix-neuf heures quinze."},{"number":2,"points":3,"correct":"B","options":["Un ballon","Un tapis","Une chaise","Un casque"],"passage":"Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin.\n\nL'animateur accueillera les participants devant la salle.","question":"Quel matériel est demandé ?","explanation":"Le passage indique : « Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin. » Cela justifie la réponse : Un tapis."},{"number":3,"points":3,"correct":"C","options":["Uniquement les livreurs","Les visiteurs sans motif","Les patients ayant rendez-vous","Toute personne souhaitant s'inscrire"],"passage":"L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale.\n\nLes demandes non urgentes seront traitées dès le retour de l'équipe d'accueil.","question":"Qui peut venir mardi matin ?","explanation":"Le passage indique : « L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale. » Cela justifie la réponse : Les patients ayant rendez-vous."},{"number":4,"points":3,"correct":"D","options":["Une sortie sans chaussures","Une course plus rapide","L'accès au parcours glissant","Un itinéraire alternatif"],"passage":"Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé.\n\nDes panneaux indiquent la déviation à l'entrée du parc. Les équipes vérifieront l'état du terrain avant de rouvrir le passage habituel.","question":"Que conseille l'annonce ?","explanation":"Le passage indique : « Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé. » Cela justifie la réponse : Un itinéraire alternatif."},{"number":5,"points":9,"correct":"D","options":["Une route inconnue de nuit","Une compétition chronométrée","Une ascension difficile","Un trajet sans montée importante"],"passage":"Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie.\n\nLe groupe peut conserver une allure tranquille et s'arrêter lorsque ce sera nécessaire. Je veux reprendre régulièrement sans transformer cette première sortie en épreuve trop difficile.","question":"Quel parcours est souhaité ?","explanation":"Le passage indique : « Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie. » Cela justifie la réponse : Un trajet sans montée importante."},{"number":6,"points":9,"correct":"A","options":["Contacter le secrétariat","Venir sans prévenir un autre jour","Annuler tous les soins","Demander à un voisin de consulter"],"passage":"Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas.\n\nLe cabinet proposera un autre créneau selon les disponibilités. Merci de signaler votre réponse rapidement pour éviter de laisser une place inutilisée.","question":"Que faire en cas d'indisponibilité ?","explanation":"Le passage indique : « Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas. » Cela justifie la réponse : Contacter le secrétariat."},{"number":7,"points":9,"correct":"B","options":["Recevoir un équipement définitif","Essayer avant de s'équiper","Participer sans jamais s'inscrire","Éviter toute séance encadrée"],"passage":"L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité.\n\nUn animateur vérifiera leur taille et expliquera les gestes de base. Vous pourrez ensuite poser vos questions avant de vous engager dans une pratique régulière.","question":"Quel est l'intérêt du prêt ?","explanation":"Le passage indique : « L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité. » Cela justifie la réponse : Essayer avant de s'équiper."},{"number":8,"points":9,"correct":"B","options":["Un départ sans accompagnateur","Des arrêts plus fréquents","Une distance doublée","La suppression des boissons"],"passage":"Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer.\n\nLe guide vérifiera les points d'eau et adaptera l'allure au groupe.","question":"Quelle adaptation est prévue ?","explanation":"Le passage indique : « Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer. » Cela justifie la réponse : Des arrêts plus fréquents."},{"number":9,"points":9,"correct":"B","options":["Aux enfants accompagnés","Aux adultes qui apprennent","Aux nageurs en compétition seulement","Aux entraîneurs professionnels"],"passage":"La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire.\n\nLes exercices commenceront dans une zone où chacun peut garder ses repères. Un échange permettra de préciser les attentes avant le premier passage dans l'eau.","question":"À qui s'adresse la séance ?","explanation":"Le passage indique : « La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire. » Cela justifie la réponse : Aux adultes qui apprennent."},{"number":10,"points":9,"correct":"D","options":["Un projet de compétition","Un déménagement en montagne","Une interdiction de courir","Une meilleure organisation du quotidien"],"passage":"Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille.\n\nJe compte aussi préparer mes affaires à l'avance pour ne pas renoncer au dernier moment.","question":"Qu'est-ce qui motive ce changement ?","explanation":"Le passage indique : « Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille. » Cela justifie la réponse : Une meilleure organisation du quotidien."},{"number":11,"points":15,"correct":"A","options":["Elle n'est pas l'objectif principal","Elle exclut les nouveaux membres","Elle détermine le droit d'entrer","Elle impose un temps identique"],"passage":"Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin.\n\nLes animateurs proposent plusieurs exercices au même endroit et expliquent les adaptations possibles. Une personne qui débute n'a pas à suivre exactement le programme d'un habitué. Le club souhaite que chacun trouve une manière de participer sans craindre de ralentir les autres. Les responsables observeront les inscriptions, mais aussi les retours après plusieurs semaines. Une séance accueillante n'atteint pas son objectif si les nouveaux venus se sentent encore incapables de revenir seuls ou de demander une pause.","question":"Quelle place est donnée à la performance ?","explanation":"Le passage indique : « Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin. » Cela justifie la réponse : Elle n'est pas l'objectif principal."},{"number":12,"points":15,"correct":"A","options":["L'atelier ne remplace pas un suivi individuel","Les animateurs prescrivent systématiquement un traitement","Aucune question ne peut être posée","Les participants reçoivent tous un diagnostic"],"passage":"Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel.\n\nLes participants peuvent parler de leurs habitudes, mais ne sont pas invités à dévoiler un dossier médical devant le groupe. Les séances abordent notamment l'organisation de la soirée et les conditions du logement. Les intervenants rappellent que des difficultés persistantes peuvent demander une consultation.","question":"Quelle limite est précisée ?","explanation":"Le passage indique : « Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel. » Cela justifie la réponse : L'atelier ne remplace pas un suivi individuel."},{"number":13,"points":15,"correct":"A","options":["Permettre différentes capacités de participation","Supprimer les explications","Réserver le parc aux spécialistes","Imposer une difficulté unique"],"passage":"Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement.\n\nLes indications ne supposent pas que l'on connaisse déjà les appareils. Des dessins montrent les positions et rappellent qu'une pause est possible. Le service souhaite accueillir les personnes qui ne fréquentent pas les salles, autant que les sportifs habituels. Les usagers pourront signaler un mouvement difficile à comprendre. Une première évaluation regardera la variété des participants et la facilité d'utilisation du parcours, plutôt que le seul nombre d'équipements installés ou la vitesse à laquelle ils sont utilisés.","question":"Quel objectif poursuit l'aménagement ?","explanation":"Le passage indique : « Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement. » Cela justifie la réponse : Permettre différentes capacités de participation."},{"number":14,"points":15,"correct":"D","options":["Pour imposer un classement plus strict","Pour limiter l'accès aux nouveaux venus","Pour remplacer toutes les sorties","Pour diversifier les façons de pratiquer"],"passage":"Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse.\n\nLes rendez-vous gardent une progression et un encadrement, mais les distances sont adaptées aux objectifs annoncés par les participants. Certains cherchent une activité après le travail ; d'autres veulent retrouver une habitude interrompue. Le responsable souhaite éviter qu'une même image de la performance fasse croire que le club n'accueille que des coureurs rapides. Les deux groupes pourront partager des rencontres et quelques exercices, sans que l'un soit considéré comme une version moins valable de l'autre.","question":"Pourquoi ce groupe est-il créé ?","explanation":"Le passage indique : « Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse. » Cela justifie la réponse : Pour diversifier les façons de pratiquer."},{"number":15,"points":15,"correct":"C","options":["L'existence d'un accueil","La diversité des horaires","La dépendance aux outils numériques","Le besoin d'un rendez-vous"],"passage":"Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau.\n\nLes personnes qui appellent reçoivent les mêmes informations sur les créneaux et les documents utiles. Les secrétaires peuvent expliquer une étape incomprise sans demander l'aide d'un proche équipé. Le centre ne veut pas supprimer les démarches en ligne, pratiques pour une partie du public. Il souhaite simplement conserver une possibilité réelle pour ceux qui ne peuvent pas les utiliser seuls. Les responsables suivront les attentes sur chaque canal pour éviter qu'un accès annoncé reste beaucoup plus difficile que l'autre.","question":"Quel obstacle cherche-t-on à réduire ?","explanation":"Le passage indique : « Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau. » Cela justifie la réponse : La dépendance aux outils numériques."},{"number":16,"points":15,"correct":"B","options":["Remplacer tous les meubles par des écrans","Agir sur l'organisation et les pauses","Exiger l'immobilité toute la journée","Supprimer les changements de tâche"],"passage":"Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement.\n\nLes salariés ont participé aux essais en indiquant les gestes qui provoquaient une gêne. Certaines tâches seront alternées et quelques équipements déplacés pour faciliter les changements de position. L'entreprise veut observer le travail réel avant de distribuer uniquement des recommandations individuelles. Une affiche pourra rappeler des repères, mais ne remplacera pas une organisation permettant effectivement de bouger.","question":"Quelle approche est adoptée ?","explanation":"Le passage indique : « Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement. » Cela justifie la réponse : Agir sur l'organisation et les pauses."},{"number":17,"points":15,"correct":"B","options":["Comparer uniquement les chaussures","Mieux comprendre l'effort réellement ressenti","Remplacer tout mouvement par un questionnaire","Garantir des progrès identiques"],"passage":"Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours.\n\nLe carnet reste personnel et sert de base à une discussion avec l'entraîneur. Les participants peuvent y signaler un sommeil court, une reprise après une absence ou un effort inhabituel dans la journée. Le club souhaite ainsi éviter une comparaison trop mécanique entre deux sorties. Les chiffres restent utiles pour suivre une progression, mais prennent un autre sens lorsqu'ils sont rapprochés des conditions dans lesquelles ils ont été obtenus.","question":"Pourquoi recueillir ces sensations ?","explanation":"Le passage indique : « Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours. » Cela justifie la réponse : Mieux comprendre l'effort réellement ressenti."},{"number":18,"points":15,"correct":"D","options":["Une participation obligatoirement gratuite","Une réservation réservée aux donateurs","Une portion proportionnelle au paiement","Un accueil indépendant de la contribution financière"],"passage":"Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie.\n\nLes participants cuisinent ensemble avant de partager le repas. Le centre souhaite préserver une activité commune plutôt que distinguer plusieurs catégories de convives. Les recettes sont pensées pour être reproduites avec un équipement courant. Le bilan prendra en compte l'équilibre financier de l'atelier, mais aussi la possibilité pour des personnes aux budgets différents de s'y retrouver régulièrement dans les mêmes conditions d'accueil.","question":"Quel principe est appliqué ?","explanation":"Le passage indique : « Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie. » Cela justifie la réponse : Un accueil indépendant de la contribution financière."},{"number":19,"points":15,"correct":"C","options":["Distribuer les dossards avant le départ","Remplacer les vestiaires","Faciliter la récupération dans un environnement apaisé","Organiser une seconde course"],"passage":"Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule.\n\nL'organisation rappelle que cet espace ne remplace pas les secours prévus pour un problème particulier. Il répond surtout au besoin de se poser après l'effort et de retrouver ses proches tranquillement. Les responsables interrogeront les participants sur sa localisation, car un équipement utile en principe peut être délaissé s'il reste difficile à trouver au milieu des autres installations.","question":"À quoi sert cet espace ?","explanation":"Le passage indique : « Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule. » Cela justifie la réponse : Faciliter la récupération dans un environnement apaisé."},{"number":20,"points":21,"correct":"C","options":["Remplacer tous les déplacements quotidiens","Sélectionner les marcheurs les plus rapides","Soutenir une pratique régulière et partagée","Atteindre une distance maximale"],"passage":"Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. Les animateurs préparent plusieurs possibilités de trajet et demandent aux nouveaux venus ce qui leur paraît réalisable. Les pauses offrent un moment pour échanger avec les autres habitants. Le centre souhaite que les personnes puissent ensuite proposer elles-mêmes une sortie. Il suivra la régularité des rencontres et les relations qui se maintiennent, sans transformer le programme en concours de distance ou de vitesse.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. » Cela justifie la réponse : Soutenir une pratique régulière et partagée."},{"number":21,"points":21,"correct":"C","options":["Aucune donnée n'a été recueillie","Les réponses concernent uniquement les enfants","Le profil des participants peut influencer les résultats","Les clubs refusent toute enquête"],"passage":"Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. Les chercheurs chercheront ensuite à rencontrer d'autres habitants, y compris ceux qui ne disposent pas d'un équipement adapté ou n'aiment pas les activités proposées. Ces réponses permettront de distinguer les préférences et les obstacles. Le premier questionnaire reste utile pour comprendre la vie des clubs, mais sa portée doit être clairement annoncée.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. » Cela justifie la réponse : Le profil des participants peut influencer les résultats."},{"number":22,"points":21,"correct":"B","options":["Confirmer que chacun l'utilise déjà","Comprendre les obstacles à une participation plus large","Supprimer toutes les activités gratuites","Fermer le terrain aux usagers actuels"],"passage":"Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. Les réponses évoquent parfois la difficulté de venir sans connaître quelqu'un, ou l'absence d'une activité souhaitée. Il ne souhaite pas simplement compter les entrées et déclarer le projet terminé. La consultation doit aider à comprendre qui utilise le lieu, qui reste à l'écart et quelles modifications pourraient changer cette situation.","question":"Pourquoi poursuivre la consultation ?","explanation":"Le passage indique : « Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. » Cela justifie la réponse : Comprendre les obstacles à une participation plus large."},{"number":23,"points":21,"correct":"D","options":["Celle entre débutants et entraîneurs uniquement","Celle entre les jours ouvrés et les congés scolaires","Celle entre deux vestiaires","Celle entre activité personnelle et évaluation au travail"],"passage":"Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. Des personnes apprécient l'offre tout en préférant se reposer ou régler une démarche pendant la pause. Elles souhaitent pouvoir choisir sans craindre un jugement sur leur attitude. La direction précisera donc le caractère facultatif du cours et demandera aux responsables de ne pas le commenter dans les entretiens.","question":"Quelle séparation souhaitent-ils préserver ?","explanation":"Le passage indique : « Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. » Cela justifie la réponse : Celle entre activité personnelle et évaluation au travail."},{"number":24,"points":21,"correct":"C","options":["Une augmentation des obstacles matériels","Un classement plus précis","Un accompagnement humain","Une fermeture des inscriptions"],"passage":"Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. Les nouveaux pratiquants peuvent avoir besoin d'explications, de repères ou d'une présence rassurante lors des premières séances. L'association cherche donc des personnes formées à cet accueil et réorganise quelques horaires. Le bilan distinguera les prêts effectués et les séances que les personnes ont pu suivre dans de bonnes conditions.","question":"Quel besoin reste présent ?","explanation":"Le passage indique : « Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. » Cela justifie la réponse : Un accompagnement humain."},{"number":25,"points":21,"correct":"C","options":["La hausse des consultations tardives constitue le résultat principal, même si les délais du lendemain augmentent pour d'autres patients.","Une baisse des annulations démontre le bénéfice des horaires étendus.","Une fréquentation de nouveaux publics compatible avec des délais et une qualité d'accueil acceptables.","Le bénéfice se mesure aux réservations supplémentaires du soir, les effets sur le service du matin pouvant être évalués séparément."],"passage":"Un centre propose des horaires de consultation plus tardifs. Il mesure ensuite les annulations et le temps d'attente, afin de vérifier que l'ouverture répond réellement à un besoin. Les responsables regarderont notamment si de nouveaux publics peuvent venir sans demander un arrangement exceptionnel. Les équipes expliqueront aussi les contraintes rencontrées après l'ouverture. L'augmentation du nombre d'heures ne sera pas présentée comme un résultat suffisant si les créneaux restent vides ou si la qualité de l'accueil diminue. Après deux mois, les réservations tardives augmentent, mais l'attente moyenne s'allonge le lendemain matin. Les responsables séparent donc la fréquentation des nouveaux créneaux, l'arrivée de personnes auparavant empêchées et les éventuelles conséquences sur le reste du service.","question":"Quel bilan permettrait de conclure à une amélioration réelle du service ?","explanation":"C exige l'accueil de nouveaux publics avec des délais et une qualité de service acceptables. A et D donnent priorité à la hausse du soir malgré les conséquences matinales; B s'en tient aux annulations et à l'occupation sans examiner les nouveaux publics ni l'attente."},{"number":26,"points":21,"correct":"A","options":["Parce que les rappels peuvent encourager certains utilisateurs mais exercer une pression sur d'autres.","L'utilisation des rappels mesure mieux l'assiduité que les choix de rythme ou de rendez-vous collectifs.","Des rendez-vous de groupe apportent à chacun une motivation supérieure aux messages de rappel individuels.","Les personnes ayant désactivé les messages semblent moins désireuses de poursuivre une pratique régulière."],"passage":"Une application de sport envoie des rappels quotidiens. Certains utilisateurs les trouvent utiles ; d'autres désactivent les messages pour éviter une pression supplémentaire. Elle recueillera les retours sur l'usage dans la durée, pas seulement lors de l'inscription. Les responsables veulent éviter qu'un outil présenté comme encourageant devienne une source de culpabilité. Ils rappellent qu'une notification ne remplace pas les conditions pratiques, le plaisir ou le soutien qui permettent de conserver une activité. Dans un groupe suivi six semaines, les utilisateurs qui désactivent les rappels ne sont pas tous moins actifs: certains préfèrent des rendez-vous collectifs. Ceux qui gardent les rappels ne les trouvent pas tous encourageants à chaque période.","question":"Pourquoi l'équipe ne peut-elle pas utiliser l'activation des rappels comme mesure directe de motivation ?","explanation":"A montre que le réglage des messages dépend aussi de la pression ressentie et du mode de pratique. B/D déduisent une motivation des notifications, C infère une supériorité générale du groupe non établie."},{"number":27,"points":21,"correct":"C","options":["Les questions sur les traitements peuvent être abordées collectivement si les situations comparées paraissent médicalement proches.","La comparaison de deux dossiers serait possible en groupe si l'identité des patients était omise dans la discussion.","Les questions générales peuvent être abordées publiquement, tandis que les situations médicales identifiables requièrent un cadre confidentiel.","Les informations pratiques peuvent être données pendant la réunion, mais les questions liées au fonctionnement des consultations doivent rester privées."],"passage":"Un médecin participe à une réunion publique sur la prévention. Il refuse de commenter les dossiers personnels dans la salle et propose des échanges confidentiels dans un autre cadre. Les personnes peuvent poser des questions sur l'organisation générale du service et sur les ressources disponibles. Les cas individuels seront abordés par les canaux habituels, dans des conditions permettant un échange adapté. Pendant la réunion, une personne demande si le traitement prescrit à son voisin convient à son propre cas. Le médecin explique le fonctionnement des consultations, mais reporte toute comparaison de dossiers à un entretien individuel.","question":"Quelle limite le médecin trace-t-il entre information collective et conseil individuel ?","explanation":"C autorise l'information générale et réserve les situations médicales individuelles au cadre confidentiel. A/B transforment la réunion en comparaison clinique; D classe à tort l'organisation des consultations comme sujet privé."},{"number":28,"points":21,"correct":"A","options":["L'accès réel dépend aussi des possibilités de transport pour rentrer chez soi, après la séance du soir.","Les personnes motorisées bénéficient moins des nouveaux créneaux parce qu'elles partent avant la fermeture des transports.","Les utilisateurs non motorisés quittent les lieux plus tôt principalement parce qu'ils préfèrent les séances courtes.","L'extension du gymnase réduit la demande de transport public le soir chez les usagers de tous les quartiers."],"passage":"Un gymnase reste ouvert plus longtemps, mais l'arrêt de bus ferme tôt. Les habitants sans voiture ne profitent pas des nouveaux créneaux. Les associations proposent de comparer les horaires du réseau et les sorties réelles du gymnase. Une meilleure coordination pourrait être plus utile qu'une nouvelle campagne d'inscription. Elle souhaite éviter que l'ouverture soit annoncée comme une amélioration identique pour tous, alors que certains habitants ne disposent pas du moyen de rentrer chez eux. Une enquête montre que les derniers utilisateurs du gymnase quittent les lieux avant la fermeture de l'établissement, précisément pour attraper le dernier autobus. Les résidents motorisés utilisent davantage le nouveau créneau que les autres.","question":"Pourquoi la simple extension de l'ouverture ne produit-elle pas les mêmes effets selon les habitants ?","explanation":"A constate que l'accès dépend du trajet retour et pas seulement de la salle ouverte. B inverse les groupes, C attribue une préférence sans preuve, D généralise un effet non mesuré."},{"number":29,"points":21,"correct":"D","options":["Les activités restent identiques pour tous mais leurs fréquences sont adaptées à l'âge et au niveau des participants.","Le programme renonce à mesurer les progrès individuels afin de ne pas réintroduire une comparaison liée au poids.","La perte de poids demeure la principale mesure, tandis que les exercices possibles varient selon les préférences.","Suivre plusieurs pratiques choisies selon les objectifs de chacun, plutôt que mesurer tous les progrès par le poids."],"passage":"Une association remplace son défi de perte de poids par un suivi de pratiques choisies avec les participants. Elle veut éviter de réduire le bien-être à un seul chiffre. Les participants discutent de ce qu'ils souhaitent rendre plus facile dans leur quotidien. Certains choisissent une promenade régulière, d'autres un moment de préparation des repas ou une reprise progressive d'activité. Le suivi sera ajusté à ces objectifs. Deux participants souhaitent des activités très différentes et fixent chacun un rythme réaliste. L'association évalue leur participation par rapport à leurs propres objectifs, au lieu de les classer à partir d'une variation de poids commune.","question":"Quel changement introduit le nouveau suivi par rapport à l'ancien défi ?","explanation":"D suit des pratiques choisies à partir des besoins et non un indicateur corporel unique. A conserve une pratique uniforme, B supprime le suivi pourtant individualisé, C maintient l'ancien critère."},{"number":30,"points":26,"correct":"D","options":["Une séance gratuite devient suffisante pour les personnes travaillant tard lorsque son programme correspond à leurs attentes.","La fréquence de présence permet de distinguer les personnes motivées avant d'examiner les contraintes familiales.","L'absence malgré la gratuité indique surtout une préférence pour des activités individuelles sans calendrier fixe.","Les modalités proposées peuvent rester incompatibles avec le travail ou les responsabilités familiales, pour certains participants."],"passage":"Les campagnes qui invitent chacun à bouger supposent parfois que le temps disponible est librement choisi. Les emplois du temps irréguliers et les charges familiales peuvent rendre difficile une activité régulière. Adapter les propositions suppose de comprendre ces contraintes plutôt que d'attribuer toute absence à un manque de volonté. Ils évaluent ensuite si ces possibilités touchent effectivement les personnes jusqu'alors absentes, au lieu de supposer que l'affichage d'une offre suffit à la rendre accessible. L'association organise une séance gratuite à 18 heures; elle constate que les mêmes personnes restent absentes lorsque leur travail finit après cette heure. Elle teste ensuite deux horaires et une formule pouvant être suivie en famille avant d'évaluer l'engagement.","question":"Quelle hypothèse l'association cherche-t-elle à distinguer du simple manque de volonté ?","explanation":"D identifie horaires et responsabilités comme des barrières d'accès. A suppose la gratuité suffisante, B/C infèrent une motivation ou une préférence de l'absence."},{"number":31,"points":26,"correct":"D","options":["L'évolution du nombre de nouveaux inscrits suffit pour comparer deux saisons, même lorsque les anciens ne reviennent pas.","La taille maximale de chaque groupe indique la part des participants qui pourront continuer une activité durable.","Le renouvellement des cartes donne la mesure de fidélité même si elles ne sont pas utilisées ensuite.","La proportion des participants encore actifs et les obstacles qui expliquent les départs, après plusieurs mois de pratique."],"passage":"Une salle sportive mesure le succès d'un programme par le nombre d'inscriptions. Des animateurs proposent aussi de regarder qui continue après trois mois et pour quelles raisons. Attirer un public et lui permettre de rester actif sont deux résultats liés, mais distincts. Ces échanges permettent de comprendre les obstacles et d'ajuster les séances plutôt que présenter le nombre d'inscrits comme une preuve complète de réussite. À l'inscription, deux groupes ont le même effectif. Trois mois plus tard, le premier conserve la moitié de ses membres et l'autre presque tous. Les animateurs souhaitent comprendre non seulement ce qui attire, mais ce qui rend la participation soutenable.","question":"Quelle information complète utilement le nombre initial d'inscriptions ?","explanation":"D suit la présence réelle et les causes de départ. A se limite au recrutement, B à une capacité potentielle, C à un acte administratif sans usage."},{"number":32,"points":26,"correct":"C","options":["Étendre l'observation à plusieurs utilisateurs afin de déterminer si les progrès se retrouvent avec des pratiques diverses.","Vérifier quels participants avaient bénéficié d'un accompagnement pendant l'essai avant d'interpréter ses résultats.","Généraliser à tous les acheteurs un effet obtenu sous des conditions accompagnées particulières.","Présenter l'outil comme une aide possible dont l'effet dépend de l'usage régulier, selon les limites connues."],"passage":"Une publicité promet une amélioration rapide grâce à un équipement. Un professionnel rappelle que les effets dépendent de l'usage, de la régularité et des situations individuelles. L'achat n'est donc pas en lui-même une preuve de bénéfice. L'utilisateur doit notamment savoir dans quelles conditions la comparaison a été réalisée. Une amélioration observée dans un essai précis ne se transforme pas automatiquement en promesse identique pour chaque personne achetant le produit. L'essai cité dans la publicité a été mené avec un accompagnement régulier, tandis que l'annonce vend seulement l'objet. Le professionnel demande de distinguer les conditions du test, la façon dont l'équipement est utilisé et la situation de la personne.","question":"Quelle inférence publicitaire le professionnel juge-t-il insuffisamment fondée ?","explanation":"C est l'extrapolation injustifiée d'un essai accompagné à tous les acheteurs. A/B/D sont des précautions ou interprétations compatibles avec les preuves disponibles."},{"number":33,"points":26,"correct":"D","options":["Le chemin bénéficie principalement aux membres de clubs qui rejoignent désormais les commerces à pied.","Les habitants qui marchent davantage le font principalement à l'occasion de sorties de loisir, non des déplacements vers les services.","L'aménagement accroît la pratique physique en orientant les nouveaux usagers vers les clubs sportifs et leurs programmes réguliers.","Il facilite des marches quotidiennes sans inscription à un programme sportif, au cours de trajets ordinaires."],"passage":"Des aménagements urbains favorisent les déplacements à pied. Leur effet dépasse les personnes qui s'inscrivent volontairement à une activité : un chemin sûr et agréable modifie aussi les trajets ordinaires. La promotion du mouvement peut ainsi passer par le cadre quotidien plutôt que par des programmes spécialisés. Les services observent donc les trajets ordinaires et les points où les habitants renoncent à marcher. Le nouveau chemin est surtout fréquenté pour rejoindre les commerces et les transports. Une partie de ses utilisateurs ne participe à aucun programme sportif, mais marche plus régulièrement parce que le trajet est devenu sûr.","question":"Quel mécanisme explique que l'aménagement touche des personnes non inscrites à une activité ?","explanation":"D rattache la marche plus fréquente aux trajets ordinaires vers commerces et transports, y compris sans programme sportif. A suppose une majorité d'adhérents, B transforme les déplacements utilitaires en loisirs et C infère une inscription aux clubs qui n'est pas observée."},{"number":34,"points":26,"correct":"A","options":["Elle permet une reprise accompagnée et adaptée sans effacer le parcours déjà engagé, même après une interruption.","Une interruption oblige le participant à revalider son parcours, même lorsque ses acquis restent documentés.","La reprise suit le même protocole pour tous afin que la difficulté du retour soit évaluée de façon comparable.","Le maintien de l'ancien dossier dispense la personne de discuter avec l'animateur des capacités au retour."],"passage":"Un programme de reprise d'activité accepte les interruptions. Les participants peuvent revenir sans recommencer toutes les démarches. Les animateurs considèrent les parcours irréguliers comme une réalité à accompagner, et non comme une faute qui justifierait l'exclusion. Les animateurs demandent simplement de reprendre contact pour adapter le retour. Ils veulent maintenir une porte ouverte, tout en organisant un groupe qui puisse accueillir les personnes sans ignorer les contraintes réelles de chacune. Une participante s'interrompt plusieurs semaines pour s'occuper d'un proche. À son retour, elle reprend à un rythme réduit après un échange avec l'animateur; son ancien dossier reste valable et ses besoins sont réévalués.","question":"En quoi l'organisation favorise-t-elle une pratique durable ?","explanation":"A réunit continuité du parcours et adaptation au retour. B efface les acquis, C uniformise les besoins, D supprime l'accompagnement prévu."},{"number":35,"points":26,"correct":"C","options":["Les entretiens servent à affiner la proportion de salariés stressés, plutôt qu'à différencier les sources de tension.","Des scores comparables justifient une intervention commune avant d'examiner les mécanismes spécifiques à chaque équipe.","Ils montrent que des scores identiques peuvent recouvrir des mécanismes différents nécessitant des réponses distinctes.","Les explications recueillies permettent de recalculer le score en donnant plus de poids aux interruptions fréquentes."],"passage":"Une enquête mesure le stress au travail avec un questionnaire très court. Elle permet de repérer des tendances, mais ne décrit pas les causes précises dans chaque service. Les responsables complètent donc les chiffres par des échanges avec les équipes. Les équipes peuvent alors expliquer les interruptions, les priorités concurrentes et les moments difficiles. Le service souhaite construire des pistes d'amélioration à partir de ce dialogue, sans considérer chaque score comme une explication déjà complète. Dans deux services, la même proportion de salariés signale un stress élevé. Les entretiens révèlent pourtant des sources différentes: interruptions fréquentes dans l'un, échéances contradictoires dans l'autre. Les responsables ne veulent pas prescrire une réponse uniforme à partir du score seul.","question":"Quel apport spécifique les échanges fournissent-ils après les questionnaires ?","explanation":"C s'appuie sur les entretiens révélant des causes différentes derrière des scores égaux: interruptions d'un côté, échéances contradictoires de l'autre. A limite à tort les échanges au taux mesuré; B traite les deux services de la même manière; D transforme une explication qualitative en recalcul non prévu."},{"number":36,"points":33,"correct":"A","options":["Des freins économiques et sociaux peuvent se cumuler, d'où l'intérêt de réponses complémentaires, dans la pratique quotidienne.","Une baisse de cotisation résout la difficulté d'accès, tandis que l'accompagnement ne fait qu'améliorer le confort.","La présence d'un proche durant la première séance explique aussi le budget disponible pour continuer à venir.","Le nombre de demandes augmente suffisamment pour conclure que les freins sociaux ont diminué chez tous."],"passage":"Un club veut rendre ses activités accessibles à tous en réduisant les cotisations. Les demandes augmentent, mais des personnes restent absentes : certaines n'osent pas venir seules, d'autres ne se reconnaissent pas dans les images utilisées. L'obstacle financier est réel, sans être la seule barrière à une pratique accueillante. L'association cherche désormais des relais dans les lieux fréquentés par ces habitants et propose des premières séances accompagnées. Elle conserve aussi les tarifs réduits, car les contraintes se cumulent souvent au lieu de se remplacer. Les responsables souhaitent éviter de conclure que les absents ne s'intéressent pas à l'activité. Ils vérifieront plutôt si les nouveaux moyens d'accueil changent les expériences des personnes qui viennent pour la première fois. L'objectif reste d'ouvrir des possibilités concrètes, sans transformer une mesure utile en réponse présentée comme suffisante à toutes les difficultés. Après la réduction du prix, davantage d'habitants consultent le programme mais certains n'entrent toujours pas dans la salle. Des séances accompagnées les amènent à essayer une première fois, tandis que d'autres participants ont encore besoin du tarif réduit pour continuer.","question":"Que révèle la combinaison des tarifs réduits et des premières séances accompagnées ?","explanation":"A reconnaît des obstacles économiques et sociaux cumulables, traités par des aides complémentaires. B et D présument qu'une mesure efface l'autre difficulté; C relie sans preuve accompagnement et budget."},{"number":37,"points":33,"correct":"B","options":["La fatigue perçue doit remplacer les pas comme indicateur unique dès que les membres ressentent un changement.","Parce que des chiffres semblables peuvent recouvrir des expériences individuelles différentes, y compris à quantité de pas égale.","Le plaisir déclaré fournit une échelle commune permettant de comparer directement les résultats de tous les participants.","La durée de marche indique mieux que le total des pas si la personne peut retrouver une activité sociale."],"passage":"Les outils de suivi comptent facilement les pas ou les minutes d'exercice. Ils décrivent moins bien le plaisir, la fatigue ou la confiance retrouvée. Un animateur utilise les chiffres comme point de discussion, sans en faire la définition complète du progrès. Ce qui se mesure simplement n'épuise pas ce qui compte pour la personne. Une personne peut marcher moins longtemps qu'une autre tout en retrouvant la possibilité de sortir de chez elle. Une autre cherche surtout à partager une activité avec des amis. L'animateur souhaite pouvoir entendre ces objectifs sans les remplacer par un classement unique. Il ne rejette pas les mesures, mais demande qu'elles restent des outils de compréhension. Les participants pourront choisir ce qu'ils veulent suivre et expliquer ce qu'ils ressentent. Deux membres atteignent le même nombre de pas. L'une se fatigue davantage qu'avant; l'autre se sent capable de reprendre un trajet qu'elle évitait. L'animateur conserve la mesure, mais discute de ce qu'elle représente réellement pour chacun.","question":"Pourquoi l'animateur ne classe-t-il pas les progrès à partir du seul nombre de pas ?","explanation":"B constate que des totaux égaux peuvent correspondre à des situations distinctes de fatigue ou d'autonomie. A/C substituent un autre classement unique, et D attribue à la durée un pouvoir de description non démontré."},{"number":38,"points":33,"correct":"A","options":["Adapter les équipements à des usages de rencontre observés après l'ouverture, sans les limiter au sport.","Sur une hausse générale de l'activité physique due aux bancs, mesurée avant les premières rencontres du quartier.","Sur la nécessité de réserver les appareils aux usagers qui les utilisent selon les exercices du plan initial.","Sur un objectif de fréquentation sportive qui demeure inchangé malgré les rencontres spontanées observées."],"passage":"Une ville installe des équipements sportifs dans un parc. Les services observent des usages imprévus : certains habitants s'y retrouvent pour discuter et font quelques mouvements ensemble. Plutôt que restreindre cet usage, ils ajoutent des bancs. Un aménagement peut produire des bénéfices différents de ceux que ses concepteurs avaient précisément anticipés. Les agents constatent que les rencontres régulières encouragent parfois des personnes jusque-là hésitantes à essayer les appareils. Ils vont donc continuer à observer le lieu à différentes heures avant de fixer de nouvelles règles. Les usagers pourront proposer de petits changements et signaler les difficultés. La commune ne veut pas transformer chaque usage imprévu en erreur à corriger. Elle cherche à comprendre ce que l'installation rend possible dans la vie du quartier, au-delà du programme exact qui avait été imaginé sur le plan initial. Lorsque les bancs sont installés, des personnes qui venaient d'abord pour discuter commencent à utiliser les appareils avec des voisins. Les agents notent cette évolution sans la traiter comme le résultat nécessairement prévu dès la conception.","question":"Sur quoi repose l'adaptation décidée par la ville ?","explanation":"A décrit l'adaptation à des usages réels, notamment les échanges et l'essai progressif des appareils. B affirme un effet général non mesuré, C restreint les usages que la ville accueille, D ignore l'ajustement du projet."},{"number":39,"points":33,"correct":"A","options":["Les séances semblent améliorer le ressenti immédiat dans les deux services; la réduction durable des heures supplémentaires coïncide avec une réorganisation, sans preuve causale isolée.","La baisse des heures supplémentaires dans le premier service montre que les séances de relaxation y ont fonctionné plus efficacement que dans le second, même si les salariés décrivent des charges de travail initiales différentes.","La proximité des effectifs permet d'isoler l'effet de la réorganisation malgré l'absence de tirage au sort.","Les déclarations positives des deux équipes rendent secondaires les différences d'heures supplémentaires observées pendant le suivi."],"passage":"Une organisation souhaite prévenir l'épuisement professionnel en proposant des séances de relaxation. Les salariés apprécient l'offre, mais demandent aussi de revoir une répartition de tâches devenue irréaliste. Un soutien individuel peut être utile sans remplacer la transformation des conditions collectives qui produisent la difficulté. Certains décrivent des journées où les demandes s'ajoutent sans que les priorités soient revues. D'autres évoquent des interruptions qui rendent difficile l'achèvement d'une tâche. Les représentants souhaitent que ces éléments soient discutés avec les responsables du service. Ils ne demandent pas de supprimer les séances proposées, mais de ne pas les utiliser comme preuve que le problème serait désormais traité. Le programme sera donc accompagné d'un examen des effectifs, des délais et des possibilités de récupération. Son intérêt dépendra aussi de cette cohérence entre aide personnelle et fonctionnement quotidien du travail. Dans un service, une séance de relaxation a lieu chaque semaine, mais la quantité de dossiers urgents ne change pas et les heures supplémentaires continuent d'augmenter. Le comité propose d'évaluer séparément les bénéfices ressentis de la séance et les effets d'une révision des délais. Pour vérifier ce qui change réellement, deux services de taille proche conservent les mêmes séances hebdomadaires pendant huit semaines. Dans le premier, les responsables révisent également les délais et répartissent les urgences; dans le second, le nombre de dossiers et les interruptions restent inchangés. Dans les deux services, les participants déclarent se sentir plus détendus immédiatement après la séance. Mais seul le premier présente une baisse durable des heures supplémentaires. Les salariés de ce premier service disent aussi avoir pu refuser certaines urgences sans justification individuelle. La direction signale que les deux équipes n'étaient pas constituées par tirage au sort et que les volumes de dossiers avaient déjà légèrement divergé avant le début de l'observation. Le comité refuse donc d'attribuer avec certitude toute la différence à la réorganisation, tout en refusant d'assimiler le ressenti à une réduction de la surcharge.","question":"Quelle interprétation des observations reste la mieux justifiée sans attribuer abusivement les résultats à une seule mesure ?","explanation":"A sépare le soulagement déclaré dans les deux services de la baisse durable des heures supplémentaires, observée seulement avec une réorganisation. B suppose un effet propre plus fort des séances; C isole abusivement un effet causal sans répartition aléatoire; D minimise une différence objective de surcharge."}]}$paper_8$::jsonb),
('tcf-reading-09','tcf-reading-2026-11-distractor-polish-v5',$paper_9${"id":"tcf-reading-09","title":"TCF Reading · Test 09","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Acheter un billet obligatoire","Assister à la séance de quinze heures","Revenir uniquement le mois prochain","Visiter gratuitement une autre ville"],"passage":"Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures.\n\nLes personnes indisponibles pourront contacter l'accueil pour un échange. La boutique restera ouverte pendant les horaires habituels du musée.","question":"Quelle solution est proposée ?","explanation":"Le passage indique : « Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures. » Cela justifie la réponse : Assister à la séance de quinze heures."},{"number":2,"points":3,"correct":"A","options":["Un carnet","Un tournevis","Une perceuse","Un robot terminé"],"passage":"L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais.\n\nLes animateurs montreront comment utiliser chaque outil. Aucun montage ne devra être commencé avant la présentation des consignes communes.","question":"Quel objet faut-il apporter ?","explanation":"Le passage indique : « L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais. » Cela justifie la réponse : Un carnet."},{"number":3,"points":3,"correct":"B","options":["Uniquement les chercheurs","Des enfants accompagnés et inscrits","Des classes sans réservation","Des mineurs obligatoirement seuls"],"passage":"Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau.\n\nUne confirmation précisera l'entrée et la durée du parcours.","question":"Qui peut venir samedi ?","explanation":"Le passage indique : « Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau. » Cela justifie la réponse : Des enfants accompagnés et inscrits."},{"number":4,"points":3,"correct":"D","options":["Tout le matériel est vendu","L'horaire est reporté d'un an","Les participants montent seuls sur le toit","L'activité se poursuit à l'intérieur"],"passage":"L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante.\n\nCette solution permet de conserver la rencontre même si les conditions extérieures sont défavorables.","question":"Que se passe-t-il en cas de nuages ?","explanation":"Le passage indique : « L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante. » Cela justifie la réponse : L'activité se poursuit à l'intérieur."},{"number":5,"points":9,"correct":"C","options":["Pour supprimer tous les résultats","Pour attendre un financement","Pour contrôler la fiabilité de l'instrument","Pour changer le sujet du projet"],"passage":"Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles.\n\nJ'ai demandé à une collègue de refaire un relevé avec un autre appareil. Nous comparerons les deux séries avant de rédiger le compte rendu et de tirer une conclusion.","question":"Pourquoi l'envoi est-il différé ?","explanation":"Le passage indique : « Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles. » Cela justifie la réponse : Pour contrôler la fiabilité de l'instrument."},{"number":6,"points":9,"correct":"C","options":["Une caméra professionnelle","Une antenne radio","Aucun télescope n'est exigé","Un grand télescope"],"passage":"Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles.\n\nLes bénévoles aideront chacun à regarder et répondront aux questions. Une carte du ciel sera distribuée pour retrouver ensuite quelques repères sans matériel complexe.","question":"Quel équipement personnel est obligatoire ?","explanation":"Le passage indique : « Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles. » Cela justifie la réponse : Aucun télescope n'est exigé."},{"number":7,"points":9,"correct":"A","options":["Une faible lumière extérieure","Un accès réservé aux vendeurs","Une exposition maximale au soleil","Une température tropicale"],"passage":"Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles.\n\nIl nous faut surtout garder les mêmes conditions pendant les essais. Nous noterons chaque changement pour comprendre ce qui pourrait expliquer une différence entre deux résultats.","question":"Quelle caractéristique du local est recherchée ?","explanation":"Le passage indique : « Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles. » Cela justifie la réponse : Une faible lumière extérieure."},{"number":8,"points":9,"correct":"A","options":["Aussi aux personnes sans formation scientifique","Uniquement aux chercheurs diplômés","Seulement aux vendeurs d'instruments","Aux participants refusant les explications"],"passage":"Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions.\n\nLes personnes souhaitant approfondir recevront des références après la rencontre, sans devoir tout comprendre dès les premières minutes.","question":"À quel public s'adresse l'événement ?","explanation":"Le passage indique : « Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions. » Cela justifie la réponse : Aussi aux personnes sans formation scientifique."},{"number":9,"points":9,"correct":"D","options":["La présence d'un animateur","L'observation des pièces","L'ouverture de l'atelier","La réparation de l'appareil"],"passage":"Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche.\n\nLes objets dangereux ou trop volumineux seront refusés, et les propriétaires repartiront avec les pièces à la fin de la séance.","question":"Quel résultat n'est pas garanti ?","explanation":"Le passage indique : « Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche. » Cela justifie la réponse : La réparation de l'appareil."},{"number":10,"points":9,"correct":"C","options":["Éviter toute répétition","Obtenir un résultat décidé d'avance","Rendre les conditions comparables","Augmenter la couleur des liquides"],"passage":"Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement.\n\nNous conserverons les autres paramètres pour mieux identifier l'effet observé. Le groupe préparera un tableau commun avant de recommencer les mesures dans les conditions prévues.","question":"Pourquoi changer les récipients ?","explanation":"Le passage indique : « Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement. » Cela justifie la réponse : Rendre les conditions comparables."},{"number":11,"points":15,"correct":"A","options":["L'heure de la mesure","Le lieu choisi","La longueur du bâton","Le nombre de saisons"],"passage":"Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée.\n\nIls notent chaque observation sur un dessin du sol, avec la date et l'état du ciel. Les journées couvertes donnent aussi lieu à une discussion sur ce qui reste visible. Leur professeur ne leur demande pas de retrouver un chiffre annoncé d'avance, mais de décrire une série cohérente. Les résultats seront comparés entre deux groupes pour repérer les difficultés de lecture. Les élèves expliqueront ensuite les limites de leur expérience, notamment ce qu'ils ne peuvent pas déduire d'une seule journée d'observation.","question":"Qu'est-ce qui varie dans leur protocole ?","explanation":"Le passage indique : « Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée. » Cela justifie la réponse : L'heure de la mesure."},{"number":12,"points":15,"correct":"B","options":["Dissimuler les méthodes employées","Rendre les tentatives infructueuses utiles à d'autres","Remplacer les expériences futures par des opinions","Prouver que toute recherche échoue"],"passage":"Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches.\n\nLe compte rendu décrit les conditions et les vérifications réalisées avant l'arrêt de la tentative. Les auteurs souhaitent rendre ces informations compréhensibles, même lorsque le résultat ne se transforme pas en application immédiate. Une autre équipe pourra ainsi comparer ses propres méthodes et identifier une différence utile.","question":"Quel intérêt présente cette publication ?","explanation":"Le passage indique : « Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches. » Cela justifie la réponse : Rendre les tentatives infructueuses utiles à d'autres."},{"number":13,"points":15,"correct":"D","options":["Elle fonctionne comme un volcan réel","Elle remplace toutes les observations","Elle permet de prévoir toute éruption","Elle simplifie la réalité"],"passage":"Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels.\n\nLes médiateurs montrent ce qui a été conservé et ce qui a été laissé de côté pour rendre l'ensemble lisible. Les visiteurs peuvent poser des questions sur la différence entre une représentation et une observation sur le terrain. Des photographies et des mesures complètent donc l'activité. Elles permettent de comprendre pourquoi plusieurs outils sont nécessaires pour étudier un phénomène dont les dimensions et les rythmes ne tiennent pas dans une salle.","question":"Quelle limite de la maquette est indiquée ?","explanation":"Le passage indique : « Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels. » Cela justifie la réponse : Elle simplifie la réalité."},{"number":14,"points":15,"correct":"C","options":["Rendre les capteurs invisibles aux oiseaux","Augmenter automatiquement les températures","Éviter une influence locale qui fausserait la comparaison","Accélérer la croissance des arbres"],"passage":"Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil.\n\nLes participants reçoivent une fiche d'installation et photographient l'emplacement choisi. Une équipe vérifiera quelques points avant d'utiliser les séries dans une carte commune. Les habitants peuvent aussi noter les changements survenus autour du capteur, comme un déplacement ou des travaux. Le projet souhaite multiplier les observations sans présenter tous les nombres recueillis comme directement comparables. Les consignes communes servent à distinguer une différence entre quartiers d'un effet produit par la manière de placer l'appareil.","question":"Pourquoi préciser leur emplacement ?","explanation":"Le passage indique : « Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil. » Cela justifie la réponse : Éviter une influence locale qui fausserait la comparaison."},{"number":15,"points":15,"correct":"D","options":["Le prix du verre","La vitesse de livraison du produit","La couleur des couvercles","La facilité d'utilisation pour divers profils"],"passage":"Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée.\n\nLes volontaires essaient plusieurs positions et expliquent les moments où la prise leur semble inconfortable. Les concepteurs notent aussi les remarques des personnes qui comprennent moins vite la forme du dispositif. L'essai ne consiste pas à choisir l'utilisateur le plus habile, mais à voir si la poignée facilite réellement le geste pour des personnes différentes. Les prototypes seront modifiés avant une seconde séance. Le groupe veut éviter qu'un bon résultat obtenu par une seule personne serve de promesse générale au moment de présenter le produit.","question":"Quel critère veulent-ils examiner ?","explanation":"Le passage indique : « Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée. » Cela justifie la réponse : La facilité d'utilisation pour divers profils."},{"number":16,"points":15,"correct":"C","options":["Éviter toute comparaison","Remplacer les images actuelles par des publicités","Observer des changements sur la durée","Garantir que rien ne change"],"passage":"Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes.\n\nLes responsables gardent les dates, les réglages et les informations sur les instruments utilisés. Les chercheurs qui consultent les archives peuvent ainsi apprécier les différences entre deux séries. L'observatoire souhaite que les anciennes données restent compréhensibles lorsque les appareils changent. Il ne conserve pas seulement de belles images, mais des éléments permettant de poser de nouvelles questions.","question":"À quoi servent les archives ?","explanation":"Le passage indique : « Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes. » Cela justifie la réponse : Observer des changements sur la durée."},{"number":17,"points":15,"correct":"D","options":["Le nombre d'affiches commerciales","Le nom du livreur","La forme de la facture","L'autonomie de la batterie"],"passage":"Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès.\n\nLes essais portent sur des usages comparables, avec les mêmes réglages. L'équipe indique les conditions retenues pour que les lecteurs puissent apprécier la portée du résultat. Elle examine aussi les situations où le gain de poids serait particulièrement utile. Un appareil destiné à rester posé ne présente pas les mêmes besoins qu'un équipement porté pendant plusieurs heures. Les résultats seront donc présentés avec plusieurs critères plutôt qu'une seule formule annonçant un progrès identique pour tous les acheteurs.","question":"Quelle information complémentaire est nécessaire ?","explanation":"Le passage indique : « Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès. » Cela justifie la réponse : L'autonomie de la batterie."},{"number":18,"points":15,"correct":"C","options":["Écarter tous les non-spécialistes","Interdire les désaccords","Mieux organiser la discussion","Fixer les réponses avant le débat"],"passage":"La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges.\n\nLes participants peuvent envoyer une question auparavant ou la poser pendant le temps d'échange. L'animatrice expliquera pourquoi certaines demandes sont rapprochées et laissera la possibilité de signaler un point oublié. La bibliothèque souhaite conserver une discussion accessible malgré la diversité du public. La chercheuse pourra préciser ce qu'elle sait et ce qui dépasse son domaine de travail.","question":"Pourquoi regrouper les questions ?","explanation":"Le passage indique : « La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges. » Cela justifie la réponse : Mieux organiser la discussion."},{"number":19,"points":15,"correct":"A","options":["Explorer le fonctionnement du dispositif","Éviter de modifier l'orientation","Ouvrir immédiatement un restaurant","Garantir une cuisson par tous les temps"],"passage":"Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement.\n\nLes participants compareront plusieurs positions et noteront le temps nécessaire dans les conditions du jour. Le responsable a prévu une solution pour le repas si le ciel se couvre durablement. Il veut éviter que cette contrainte empêche de poursuivre les observations. Le groupe discutera ensuite de ce que l'essai montre réellement et des situations où un tel appareil peut être utile.","question":"Quel est l'objectif principal ?","explanation":"Le passage indique : « Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement. » Cela justifie la réponse : Explorer le fonctionnement du dispositif."},{"number":20,"points":21,"correct":"B","options":["Les essais sur petites pièces sont toujours inutiles","Le changement d'échelle doit être vérifié","Les matériaux sont déjà interdits","Toute comparaison est impossible"],"passage":"Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. Les spécialistes devront notamment examiner la résistance dans la durée et les contraintes de fabrication. Une petite pièce permet de contrôler facilement certaines conditions qui deviennent plus difficiles à maintenir ailleurs. Le laboratoire souhaite publier un résultat utile sans lui attribuer une portée que l'expérience n'a pas encore vérifiée. Les partenaires pourront ensuite choisir les essais nécessaires à leur propre projet.","question":"Quelle prudence expriment-ils ?","explanation":"Le passage indique : « Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. » Cela justifie la réponse : Le changement d'échelle doit être vérifié."},{"number":21,"points":21,"correct":"C","options":["Éliminer les artisans du projet","Choisir uniquement la meilleure photographie","Croiser mesures techniques et expérience d'usage","Remplacer toute mesure par une anecdote"],"passage":"Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. Un outil rapide sur une table d'essai peut être difficile à nettoyer, à ranger ou à utiliser avec des gants. Les artisans décrivent ces situations avec des exemples. L'équipe veut intégrer ces remarques pendant qu'il est encore possible de modifier le prototype. La consultation ne remplace pas les mesures ; elle aide à choisir celles qui correspondent aux difficultés réellement rencontrées.","question":"Quel est l'intérêt de l'échange ?","explanation":"Le passage indique : « Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. » Cela justifie la réponse : Croiser mesures techniques et expérience d'usage."},{"number":22,"points":21,"correct":"B","options":["Un laboratoire et un musée","Un potentiel et un résultat déjà généralisable","Une expérience et une absence totale de résultat","Deux découvertes nécessairement opposées"],"passage":"Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. Les journalistes sont invités à expliquer la taille de l'essai et les étapes encore nécessaires. Les chercheurs ne souhaitent ni minimiser une piste intéressante, ni laisser croire qu'elle donne déjà une solution disponible pour tous.","question":"Que faut-il distinguer ?","explanation":"Le passage indique : « Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. » Cela justifie la réponse : Un potentiel et un résultat déjà généralisable."},{"number":23,"points":21,"correct":"A","options":["Relier les mesures aux situations vécues","Remplacer la carte par des votes","Annuler toutes les températures enregistrées","Garantir une météo uniforme"],"passage":"Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. Certains points sont très chauds mais peu fréquentés, tandis que d'autres accueillent de longues attentes sans ombre. Les responsables souhaitent distinguer ces situations avant de décider où intervenir. Les témoignages ne changent pas la température mesurée ; ils apportent une information sur son importance dans la vie quotidienne.","question":"Pourquoi ajouter ces témoignages ?","explanation":"Le passage indique : « Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. » Cela justifie la réponse : Relier les mesures aux situations vécues."},{"number":24,"points":21,"correct":"B","options":["L'absence de tout réglage","La vérification des mesures","La suppression des relevés","L'achat d'un appareil plus lourd"],"passage":"Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. La notice fournit une procédure courte et un repère pour contrôler l'appareil. Les utilisateurs peuvent signaler une difficulté au distributeur ou à l'association qui organise les relevés. Un instrument accessible financièrement reste utile si les personnes savent aussi dans quelles conditions elles peuvent se fier aux valeurs qu'il affiche.","question":"Quelle exigence demeure ?","explanation":"Le passage indique : « Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. » Cela justifie la réponse : La vérification des mesures."},{"number":25,"points":21,"correct":"D","options":["Une ouverture rapide permet de diagnostiquer correctement la panne sans vérifier si la pièce concernée est vendue séparément.","Remplacer le mécanisme entier peut simplifier la réparation, même si seule une pièce fragile est défectueuse.","Une ouverture rapide rend la réparation accessible dès lors que le mécanisme complet est proposé à la vente.","Parce que le diagnostic et l'accès à l'élément à remplacer conditionnent aussi la réparation effective, sur le terrain."],"passage":"Un concours récompense une solution réparable avec des outils courants. Le jury regarde aussi les pièces détachées disponibles ; une conception démontable serait peu utile sans possibilité de remplacer les éléments. Les candidats présentent un exemple de démontage et expliquent les outils nécessaires. Le jury demande aussi comment un utilisateur pourra identifier la pièce défectueuse. Il souhaite distinguer une possibilité théorique d'ouverture et une réparation réellement réalisable. Un appareil s'ouvre en moins de cinq minutes, mais sa pièce la plus fragile n'est vendue qu'avec l'ensemble du mécanisme. Un autre demande un démontage plus long mais permet l'achat de l'élément seul. Le jury compare alors faisabilité matérielle et réparation accessible.","question":"Pourquoi la facilité de démontage ne suffit-elle pas à désigner le produit le plus réparable ?","explanation":"D exige l'identification de la panne et l'accès réel à la pièce à remplacer. A et C présument que l'ouverture ou la vente d'un ensemble suffit à la réparation accessible; B néglige la difficulté et le coût d'un remplacement intégral pour une seule pièce."},{"number":26,"points":21,"correct":"A","options":["Confronter des hypothèses divergentes aux mêmes observations et à des mesures qui pourraient les départager.","Les spécialistes doivent choisir l'explication la plus largement admise avant de recueillir de nouvelles mesures.","L'écart entre leurs hypothèses rend les relevés communs trop incertains pour être comparés efficacement.","Leur désaccord tient principalement à des méthodes différentes qu'ils n'ont pas encore cherché à harmoniser."],"passage":"Des scientifiques expliquent leur travail dans des ateliers publics. Ils présentent leurs désaccords sur certaines interprétations sans remettre en cause les observations communes. Les visiteurs découvrent des méthodes communes de vérification, mais aussi des questions qui restent ouvertes. Les intervenants expliquent comment ils comparent leurs interprétations et quelles observations pourraient les conduire à changer d'avis. Le programme veut donner une image plus précise du travail scientifique, sans le réduire à une collection de certitudes ni à une simple opposition d'opinions sans critères partagés. Deux spécialistes utilisent les mêmes mesures, mais l'un attribue l'écart à l'appareil et l'autre à une variation naturelle. Ils présentent un prochain relevé qui pourrait départager ces hypothèses plutôt que demander au public de choisir par préférence.","question":"Que révèle le désaccord présenté pendant l'atelier ?","explanation":"A montre que les hypothèses partagent des observations et peuvent être départagées par des tests. B demande une adhésion préalable, C nie la comparabilité, D attribue le désaccord à des méthodes divergentes alors que les mesures sont communes."},{"number":27,"points":21,"correct":"A","options":["Il aide à détecter les anomalies manquées par le logiciel avant le jugement humain, par un contrôle ciblé.","L'examen des images non signalées confirme la fiabilité globale du tri tant qu'aucune anomalie n'a été signalée.","Le contrôle des images rejetées permet de réduire l'intervention des lecteurs humains après une première validation automatique.","Le contrôle sert surtout à estimer combien de temps le logiciel économise sur les images ordinaires sans anomalie."],"passage":"Un logiciel repère des anomalies dans des photographies. Les cas signalés sont ensuite examinés par une personne. L'outil accélère le tri, mais ne remplace pas la décision finale. Les personnes chargées de la lecture finale doivent comprendre les erreurs possibles et les limites des images utilisées. Le laboratoire conserve aussi des exemples où le logiciel n'a rien signalé, afin de vérifier ce qu'il pourrait manquer. Le logiciel détecte souvent de faibles contrastes mais manque parfois une anomalie à la périphérie. Le laboratoire vérifie des images signalées et non signalées, puis confie le jugement final à un lecteur formé.","question":"Quel rôle joue l'examen d'images que le logiciel n'a pas signalées ?","explanation":"A décrit la recherche d'anomalies manquées pour vérifier les faux négatifs. B prend l'absence d'alerte pour preuve, C réduit à tort la supervision, D limite l'évaluation à la vitesse."},{"number":28,"points":21,"correct":"C","options":["Le changement d'appareil confirme un effet de la température, mais montre que les autres paramètres de préparation sont secondaires.","La reproduction partielle établit que l'appareil n'influence pas le résultat si la température est conservée.","Le résultat semble transférable sous certaines conditions de préparation qu'il faut expliciter, pour ce type de matériau.","La dépendance à la température réduit la fiabilité initiale au point de devoir suspendre toute conclusion."],"passage":"Une équipe répète une expérience dans un second laboratoire. Les conditions sont décrites précisément afin de comprendre d'éventuelles différences. Les équipes gardent une trace des réglages et discutent des écarts avant de modifier leur protocole. Elles veulent distinguer un effet du matériel d'une différence liée à la préparation. Il reste essentiel pour savoir dans quelles conditions un résultat peut être utilisé par d'autres personnes et avec quel degré de confiance. Le second laboratoire retrouve l'effet avec un appareil différent, mais seulement lorsque les échantillons sont préparés à la même température que dans le premier. Les chercheurs enregistrent ce paramètre pour préciser la portée de l'observation.","question":"Quelle conclusion est justifiée par la reproduction partielle du résultat ?","explanation":"C reconnaît la reproduction sous une condition de température qu'il faut préciser. A écarte sans preuve d'autres paramètres de préparation; B généralise l'indépendance du matériel; D veut suspendre toute conclusion alors que la portée de l'effet a été mieux définie."},{"number":29,"points":21,"correct":"C","options":["La bonne démonstration explique l'adoption si l'invention atteint la performance attendue du public.","Le coût d'entretien explique l'abandon de la première invention davantage que la difficulté d'intégrer ses gestes aux habitudes de travail.","L'adoption dépend aussi des coûts et des pratiques des utilisateurs concernés, au-delà de la performance technique.","La première invention a échoué surtout à cause des gestes inhabituels, tandis que les frais de maintenance semblent moins déterminants."],"passage":"Une exposition présente des inventions abandonnées. Certaines avaient de bonnes performances techniques, mais ne répondaient pas aux pratiques ou aux moyens des utilisateurs. Les visiteurs peuvent ainsi suivre une histoire moins simple qu'une opposition entre réussite et mauvaise invention. Le musée souhaite montrer que l'adoption d'un objet dépend de plusieurs acteurs et de contraintes concrètes, qui ne sont pas toujours visibles dans une démonstration technique réalisée devant un public enthousiaste. Une invention démontrée avec succès exigeait toutefois une maintenance chère et des gestes absents des habitudes du public visé. Une autre, moins spectaculaire, a été adoptée grâce à son intégration facile dans le travail courant.","question":"Que met en évidence la comparaison des deux inventions ?","explanation":"C articule performance, coût d'entretien et facilité d'intégration aux pratiques. A introduit la visibilité commerciale comme facteur principal non documenté; B et D attribuent la différence à une seule des contraintes sans fondement pour les départager."},{"number":30,"points":26,"correct":"B","options":["Une moyenne plus élevée permettrait de distinguer directement les résultats dispersés sans consulter les notes individuelles.","Une moyenne identique peut masquer des distributions et des besoins différents, dans les classes étudiées.","Une distribution présentant des extrêmes donne nécessairement une moyenne trompeuse qu'il faudrait recalculer autrement.","Deux groupes ayant la même moyenne montrent des performances comparables dans presque toutes les catégories d'élèves."],"passage":"Un chiffre moyen résume une série de mesures, mais peut masquer des écarts importants. Une médiatrice montre deux ensembles ayant la même moyenne et des répartitions très différentes. L'indicateur reste correct ; sa lecture doit être complétée. Elle invite donc le public à regarder plusieurs valeurs et les écarts entre elles. Les participants apprennent à poser une question sur ce qu'un résumé laisse visible ou rend plus difficile à voir. Une classe et une autre obtiennent une note moyenne de 12; dans la première, presque tous se situent autour de 12, tandis que la seconde rassemble surtout des notes très faibles et très fortes. La moyenne ne change pas, mais les besoins d'accompagnement sont différents.","question":"Pourquoi le même chiffre moyen conduit-il ici à des interprétations distinctes ?","explanation":"B distingue moyenne et répartition des notes. A et D infèrent la dispersion d'un résumé insuffisant, C qualifie la moyenne d'erronée alors qu'elle peut être exacte."},{"number":31,"points":26,"correct":"B","options":["Les pannes apparues plus tard devraient invalider les mesures de performance réalisées sous l'assistance du concepteur.","Un fonctionnement ponctuel assisté ne permet pas, seul, d'établir la fiabilité dans les conditions ordinaires, sur plusieurs jours.","Le maintien d'une assistance technique pendant le pilote permettrait de prédire plus sûrement son usage quotidien sans suivi.","La démonstration ne doit être prise en compte que si les conditions du site pilote sont strictement identiques."],"passage":"Un prototype fonctionne en démonstration sous la surveillance de ses concepteurs. Pour apprécier son usage futur, il faut aussi observer l'entretien, les erreurs ordinaires et les contraintes des lieux d'installation. La réussite ponctuelle ne constitue pas encore un bilan d'utilisation. Le fabricant souhaite que les futurs utilisateurs puissent apprécier l'écart entre une possibilité technique montrée une fois et un service fiable dans leurs propres conditions de travail. En laboratoire, le concepteur corrige aussitôt chaque blocage. Sur le site pilote, les utilisateurs ne disposent pas de cette présence permanente et signalent des pannes après plusieurs jours. Une démonstration courte ne révèle pas les mêmes problèmes.","question":"Quelle limite d'évaluation illustre la différence entre la démonstration et le site pilote ?","explanation":"B constate qu'un essai ponctuel accompagné ne mesure pas la fiabilité durable. A invalide abusivement la performance instantanée, C continue de masquer les problèmes de maintenance, D impose des conditions identiques plutôt qu'une évaluation contextualisée."},{"number":32,"points":26,"correct":"B","options":["Les fiches de provenance suffisent à analyser de nouveaux phénomènes sans reprendre de mesures sur les spécimens.","Elles relient des observations nouvelles au contexte des prélèvements anciens, indispensable pour interpréter les nouvelles mesures.","La localisation initiale assure la validité d'hypothèses futures même lorsque leurs méthodes ont profondément changé.","Les informations anciennes restent plus fiables que les nouvelles analyses lorsqu'un instrument différent est employé."],"passage":"Les collections anciennes d'un musée peuvent servir à de nouvelles recherches. Des méthodes récentes révèlent des informations que les premiers collecteurs ne pouvaient pas observer. La conservation maintient ainsi des possibilités de questions futures, pas seulement le souvenir d'un savoir déjà établi. Les chercheurs peuvent revenir sur des spécimens avec des questions nouvelles. La valeur d'une collection dépend alors aussi des descriptions et des conditions de conservation qui permettent de comprendre ce qui a été recueilli à l'époque. Des échantillons anciens ont été conservés avec leurs lieux de prélèvement. Une nouvelle technique permet de mesurer aujourd'hui une propriété inconnue à l'époque; sans ces informations sur l'origine des échantillons, l'analyse aurait moins de portée.","question":"Pourquoi les informations de collecte participent-elles à la valeur scientifique des spécimens ?","explanation":"B montre que le contexte d'origine donne un sens aux mesures réalisées plus tard. A/C font des métadonnées une preuve suffisante, D les oppose aux méthodes récentes au lieu de les associer."},{"number":33,"points":26,"correct":"D","options":["La plage ajoutée évite de comparer les catégories, car le graphique décrit désormais une variation possible plutôt qu'une valeur.","La représentation d'une marge d'erreur réduit directement l'incertitude des mesures sur lesquelles le graphique repose.","Une seconde couche graphique rend les catégories plus comparables parce qu'elles disposent de davantage d'indicateurs visibles.","Elle rend visible l'incertitude susceptible de modifier la comparaison de deux estimations apparemment bien ordonnées."],"passage":"Une représentation graphique peut simplifier un ensemble complexe sans le trahir. Le risque apparaît lorsqu'elle efface une limite essentielle, par exemple une incertitude sur une estimation. La clarté ne consiste donc pas toujours à retirer des informations, mais à rendre visibles celles qui changent l'interprétation. Le médiateur présente les choix de représentation et invite les lecteurs à comparer deux versions. Dans une première version, l'estimation est représentée par une barre unique; dans la seconde, une plage d'incertitude est ajoutée. Le public comprend alors que deux catégories présentées dans un ordre précis pourraient en réalité être très proches.","question":"En quoi la seconde représentation est-elle plus fidèle malgré un élément graphique supplémentaire ?","explanation":"D rend visible l'incertitude pouvant modifier l'interprétation du classement. A évite à tort la comparaison, B confond représentation et réduction de l'erreur, C attribue la justesse au nombre d'éléments."},{"number":34,"points":26,"correct":"B","options":["L'observation peut retarder la mise au point technique de prototypes qui respectent déjà parfaitement le cahier des charges.","Qu'une solution ingénieuse réponde à un problème mal défini avec les usagers, avant tout choix de prototype.","La consultation aide à améliorer les prototypes, mais ne remet pas en cause la définition initiale du problème.","Il serait préférable de tester les solutions puis de reformuler le besoin, afin de préserver l'inventivité initiale."],"passage":"Un programme encourage les jeunes à inventer rapidement une solution. Les animateurs ajoutent ensuite une étape d'observation du problème avec les utilisateurs. Une réponse ingénieuse peut être mal orientée si la difficulté initiale a été définie sans ceux qui la rencontrent. Le centre souhaite préserver l'imagination des participants tout en l'orientant vers une difficulté qu'ils ont suffisamment comprise pour proposer une réponse réellement pertinente. Deux prototypes répondent parfaitement à la consigne écrite, mais les personnes censées s'en servir expliquent qu'elles rencontrent un problème différent. Les animateurs font reformuler le besoin avant de choisir lequel développer.","question":"Quel risque l'étape d'observation vise-t-elle à réduire ?","explanation":"B évite de développer une réponse technique à un problème mal défini avec les utilisateurs. A se concentre sur le délai du développement; C conserve à tort le cadrage écrit sans le réviser; D reporte l'observation jusqu'après la réalisation du prototype."},{"number":35,"points":26,"correct":"A","options":["Elle rend visibles les conclusions révisées à partir de preuves nouvelles, ainsi que les observations contradictoires.","La révision conserve les deux hypothèses comme aussi plausibles malgré des mesures nouvelles plus précises.","Elle montre surtout que les résultats initiaux manquaient de précision, sans expliciter le raisonnement conduisant à leur révision.","Elle confirme la solidité de l'interprétation initiale et présente les données contraires comme une limite mineure de l'étude."],"passage":"Une publication scientifique accepte qu'une hypothèse soit corrigée à la lumière de nouveaux résultats. Ce changement n'est pas automatiquement une preuve d'incompétence initiale. Il peut manifester une démarche qui accepte de distinguer ce qui était plausible de ce que les observations permettent désormais d'affirmer. Ils souhaitent que le lecteur puisse suivre le raisonnement, plutôt que prendre la modification comme une simple contradiction sans explication. Une équipe avait défendu une explication raisonnable avec les mesures disponibles. Une nouvelle série plus précise la contredit; les auteurs publient ce qui change et distinguent l'ancienne incertitude de la conclusion désormais mieux étayée.","question":"Pourquoi la correction de l'hypothèse peut-elle renforcer la confiance dans la démarche ?","explanation":"A donne au lecteur le raisonnement et les observations qui motivent la révision. B maintient à égalité une explication désormais contredite; C omet à tort le raisonnement rendu public; D minimise des données qui conduisent à changer l'hypothèse."},{"number":36,"points":33,"correct":"D","options":["Financer les projets dont les méthodes sont solides sans demander de présenter leur progression durant les premières années.","Comparer seulement le potentiel d'application rapide des résultats, même lorsque les méthodes sont exploratoires.","Exiger une prévision des usages futurs, mais accepter un calendrier plus long pour les travaux fondamentaux.","Suivre les méthodes et résultats sans exiger d'application commerciale immédiatement prévisible, au cours du projet exploratoire."],"passage":"Une fondation souhaite ne financer que des recherches dont l'application serait immédiatement prévisible. Des chercheurs rappellent que certaines méthodes utiles aujourd'hui proviennent de travaux d'abord motivés par des questions fondamentales. Exiger d'avance un bénéfice précis peut écarter des explorations dont l'intérêt se révèle autrement ou plus tard. Les responsables de la fondation craignent de financer des travaux dont ils ne pourraient pas annoncer rapidement l'utilité au public. Les chercheurs proposent donc des comptes rendus qui rendent visible la progression des questions et des méthodes. Ils ne demandent pas de renoncer à tout bilan. Ils veulent seulement éviter qu'un calendrier trop court et une définition unique du bénéfice empêchent d'explorer des pistes importantes. La discussion porte ainsi sur les formes de responsabilité d'un projet, et sur la manière d'expliquer un travail dont les effets ne peuvent pas toujours être prévus avec précision au moment de son lancement. Une proposition de recherche fondamentale ne promet pas d'application dans les deux ans mais présente des méthodes reproductibles et des jalons mesurables. Le comité doit décider si cette forme de suivi peut satisfaire son exigence de responsabilité.","question":"Quelle solution correspond au compromis proposé par les chercheurs ?","explanation":"D retient des comptes rendus sur méthodes et questions sans exiger une application commerciale prévisible. A abandonne le suivi; B/C réintroduisent un critère d'usage prédéterminé au lieu d'évaluer la progression."},{"number":37,"points":33,"correct":"D","options":["Elle permet de prédire le prochain épisode en utilisant la zone commune aux deux hypothèses de pluie.","Elle indique que la route doit être fermée sans délibération dès lors que les deux cartes montrent un risque.","Elle montre que l'exposition de l'axe reste constante, mais ne dit rien de la vulnérabilité à protéger.","Elle identifie une vulnérabilité présente sous plusieurs hypothèses, sans transformer les cartes en certitudes, dans la décision locale."],"passage":"Une simulation aide une commune à anticiper les crues. Ses cartes dépendent d'hypothèses sur la pluie et l'état des sols. Les responsables les utilisent pour comparer des scénarios, sans les présenter comme une photographie certaine de l'avenir. La force de l'outil tient à l'explicitation des possibles, non à la disparition de l'incertitude. La commune publiera les hypothèses principales et présentera plusieurs situations aux habitants. Certaines cartes permettront d'examiner un épisode fréquent, d'autres un événement plus rare mais plus grave. Les responsables devront choisir des aménagements qui restent utiles malgré cette diversité. Ils souhaitent que l'outil aide à comprendre leurs décisions, sans lui attribuer la responsabilité de les prendre seul. Les personnes concernées pourront ainsi discuter des priorités et des limites du dispositif. Deux cartes reposent sur des pluies de fréquences différentes. La zone inondée varie fortement, mais une route figure dans les deux périmètres. Les élus envisagent de sécuriser d'abord cet axe sans affirmer qu'une carte prédit le prochain épisode.","question":"En quoi la comparaison de scénarios aide-t-elle la décision sur la route ?","explanation":"D tire des scénarios une vulnérabilité commune, sans confondre hypothèse et prévision. A prétend dater l'épisode; B retire aux élus le choix d'aménagement; C ignore la vulnérabilité précisément repérée."},{"number":38,"points":33,"correct":"D","options":["Il établit qu'une omission volontaire des auteurs initiaux a créé la différence entre les deux laboratoires.","Il rend la conclusion initiale inutile puisqu'une modification de préparation rapproche les résultats obtenus.","Il prouve que la comparaison entre laboratoires n'a d'intérêt que lorsque tous les instruments sont identiques.","Il révèle une condition expérimentale influente et précise quand le résultat publié peut être reproduit."],"passage":"Une équipe cherche à reproduire un résultat publié et obtient un écart. Avant d'accuser les premiers auteurs, elle examine les instruments, les matériaux et les conditions de l'essai. Un désaccord expérimental devient une source d'information lorsqu'on recherche ce qui le produit, plutôt que de le réduire immédiatement à une faute. Les deux laboratoires échangent leurs observations et préparent de nouveaux essais. Ils découvrent parfois qu'un détail jugé secondaire dans le premier compte rendu modifie le résultat. Cette découverte peut enrichir la compréhension du phénomène, même si elle complique l'annonce initiale. Les chercheurs souhaitent rendre ces étapes visibles pour éviter que toute différence soit interprétée comme un conflit personnel. La publication des méthodes devient alors aussi importante que celle de la conclusion. D'autres équipes pourront examiner les mêmes éléments, essayer des conditions différentes et préciser progressivement la portée de ce qui a été observé. Le groupe découvre que l'échantillon avait été séché plus longtemps dans le second laboratoire. Lorsqu'il harmonise ce détail, les résultats se rapprochent, sans rendre inutile la publication de l'écart initial.","question":"Quelle valeur scientifique conserve l'écart initial une fois le détail identifié ?","explanation":"D montre que l'écart révèle un facteur de préparation influent et précise les conditions de reproductibilité. A suppose une intention malhonnête; B efface à tort la découverte; C exige une identité instrumentale non soutenue."},{"number":39,"points":33,"correct":"A","options":["Maintenir une série commune aux sites et distinguer les mesures exploratoires sur l'exposition locale, sans mélanger les résultats lors des comparaisons.","Mesurer les sites selon les horaires jugés les plus représentatifs par chaque quartier, puis corriger les différences après la collecte.","Remplacer la série normalisée par les relevés au niveau des poussettes, puisque le pic découvert à l'arrêt confirme leur priorité scientifique.","Les mesures supplémentaires deviennent directement comparables à la série principale lorsqu'elles sont relevées au même arrêt."],"passage":"Des citoyens participent à une enquête sur la qualité de l'air. Les scientifiques les associent au choix des lieux, mais conservent un protocole commun de mesure. La participation n'exige pas l'abandon de la rigueur ; elle peut enrichir les questions posées tout en maintenant des conditions qui rendent les résultats comparables. Les habitants connaissent des endroits où les personnes attendent longtemps et des horaires où la circulation change. Ils apportent ces repères lors de la préparation des relevés. Les spécialistes expliquent ensuite les règles de placement et les vérifications nécessaires pour éviter des comparaisons trompeuses. Le groupe discutera les résultats ensemble, avec les circonstances de chaque mesure. Les participants ne deviennent pas interchangeables, mais leurs connaissances se complètent. Le projet souhaite ainsi produire des informations plus utiles au territoire, tout en permettant au public de comprendre comment un résultat est construit et quelles questions il laisse encore ouvertes. Les riverains signalent un arrêt d'autobus très fréquenté au moment où les voitures se concentrent. Les scientifiques retiennent le lieu, mais imposent la même hauteur de capteur et les mêmes périodes de mesure que pour les autres sites. Après une première campagne, le groupe découvre un pic de pollution à l'arrêt proposé par les riverains. Une association souhaite ajouter un capteur au niveau des poussettes et mesurer uniquement les heures de sortie d'école, alors que le protocole initial impose une hauteur commune et des créneaux identiques dans tous les lieux comparés. Les scientifiques proposent de conserver la série standardisée pour les comparaisons entre sites et d'effectuer, en complément clairement identifié, des relevés exploratoires à la hauteur suggérée. Ces relevés supplémentaires pourraient éclairer l'exposition des enfants, sans être directement mêlés à la série principale. Lors d'un essai, les deux hauteurs donnent effectivement des valeurs différentes au même arrêt. Le rapport précise donc à quelle méthode appartient chaque résultat et demande de nouveaux relevés avant de conclure sur la cause de l'écart. Les habitants participent au choix des questions complémentaires, mais les règles de la série commune ne changent pas au gré des sites.","question":"Quelle organisation des relevés permet de répondre à une question locale sans invalider la comparaison principale ?","explanation":"A conserve une série standardisée entre sites et sépare les mesures exploratoires réalisées à d'autres hauteurs. B change les créneaux selon le quartier; C supprime la série commune; D confond le même lieu de mesure avec une méthode directement comparable."}]}$paper_9$::jsonb),
('tcf-reading-10','tcf-reading-2026-11-distractor-polish-v5',$paper_10${"id":"tcf-reading-10","title":"TCF Reading · Test 10","seconds":3600,"version":"tcf-reading-2026-11-distractor-polish-v5","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Rencontrer tous les enseignants","Travailler dans la salle","Emprunter des livres","Inscrire une classe"],"passage":"La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là.\n\nLe personnel pourra orienter les lecteurs vers les rayons accessibles. Merci de respecter les espaces réservés au travail silencieux.","question":"Quel service est disponible dimanche ?","explanation":"Le passage indique : « La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là. » Cela justifie la réponse : Travailler dans la salle."},{"number":2,"points":3,"correct":"B","options":["Une personne déjà experte","Une personne débutante","Uniquement un diplômé","Un professeur seulement"],"passage":"Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté.\n\nUne première rencontre permettra de présenter les objectifs et l'organisation. Les candidats peuvent poser leurs questions avant de confirmer.","question":"Qui peut s'inscrire ?","explanation":"Le passage indique : « Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté. » Cela justifie la réponse : Une personne débutante."},{"number":3,"points":3,"correct":"C","options":["Dans une autre école","Uniquement par courrier","Au secrétariat mardi","À la bibliothèque dimanche"],"passage":"Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi.\n\nLe secrétariat demandera simplement le nom de l'élève et sa classe. Les documents ne seront pas laissés dans un lieu ouvert à tous.","question":"Où un élève absent pourra-t-il récupérer sa copie ?","explanation":"Le passage indique : « Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi. » Cela justifie la réponse : Au secrétariat mardi."},{"number":4,"points":3,"correct":"D","options":["Un cours obligatoire pour les parents","Un examen pour les enfants","Une sortie scolaire payante","Une garde pendant la réunion"],"passage":"La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine.\n\nLe service est proposé pendant toute la durée des échanges. Merci de signaler le nombre d'enfants au moment de confirmer votre venue.","question":"Quel accompagnement est proposé ?","explanation":"Le passage indique : « La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine. » Cela justifie la réponse : Une garde pendant la réunion."},{"number":5,"points":9,"correct":"C","options":["Un changement définitif de professeur","Une dispense de tous les cours","Les exercices qu'elle manquera","Un diplôme sans examen"],"passage":"Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ?\n\nJe veux éviter de prendre du retard avant le prochain chapitre. Si certains points demandent une explication, je contacterai ensuite le formateur pour savoir comment les reprendre.","question":"Que demande cette personne ?","explanation":"Le passage indique : « Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ? » Cela justifie la réponse : Les exercices qu'elle manquera."},{"number":6,"points":9,"correct":"A","options":["Un nombre minimal de confirmations","La réussite à un concours","Une expérience professionnelle précise","L'achat immédiat d'un manuel"],"passage":"Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement.\n\nLe centre vous indiquera aussi les autres créneaux possibles. Si le groupe n'ouvre pas, vous pourrez choisir une autre formule ou renoncer sans frais.","question":"Quelle condition détermine l'ouverture ?","explanation":"Le passage indique : « Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement. » Cela justifie la réponse : Un nombre minimal de confirmations."},{"number":7,"points":9,"correct":"D","options":["Être vendu en classe","Décorer définitivement l'école","Remplacer l'inscription","Soutenir une prise de parole"],"passage":"Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale.\n\nVous pourrez expliquer pourquoi vous l'avez choisi et raconter un souvenir qui lui est associé. Aucun objet coûteux ou particulièrement original n'est nécessaire pour participer à cet exercice.","question":"À quoi servira l'objet ?","explanation":"Le passage indique : « Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale. » Cela justifie la réponse : Soutenir une prise de parole."},{"number":8,"points":9,"correct":"D","options":["Un cours de dessin artistique uniquement","Un changement de lieu de travail","Une préparation à tous les examens","Un apprentissage lié à une tâche précise"],"passage":"Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ?\n\nJ'utilise déjà ces documents au quotidien, mais certains symboles restent difficiles à interpréter.","question":"Quel besoin est exprimé ?","explanation":"Le passage indique : « Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ? » Cela justifie la réponse : Un apprentissage lié à une tâche précise."},{"number":9,"points":9,"correct":"B","options":["Écarter les débutants","Partager une méthode sans l'imposer","Défendre une solution obligatoire","Comparer les notes publiquement"],"passage":"La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous.\n\nL'animateur aidera à comparer les pratiques et les situations dans lesquelles elles fonctionnent.","question":"Quelle attitude est attendue ?","explanation":"Le passage indique : « La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous. » Cela justifie la réponse : Partager une méthode sans l'imposer."},{"number":10,"points":9,"correct":"A","options":["En autonomie avec une aide possible","Sans aucun travail prévu","Avec un examen permanent","Uniquement en présence du directeur"],"passage":"Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes.\n\nLes participants auront quelques exercices à terminer et pourront organiser leur temps. Une rencontre courte permettra de vérifier les difficultés avant de poursuivre la suite du programme.","question":"Comment sont organisés les après-midi ?","explanation":"Le passage indique : « Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes. » Cela justifie la réponse : En autonomie avec une aide possible."},{"number":11,"points":15,"correct":"A","options":["Multiplier les moyens d'accès à la consigne","Imposer une seule méthode","Réserver l'audio aux enseignants","Supprimer la lecture pour tous"],"passage":"Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide.\n\nLes supports sont préparés avec le même contenu pour que personne ne reçoive une consigne différente par erreur. Les élèves peuvent réécouter un passage ou revenir au texte lorsqu'un mot leur échappe. L'équipe souhaite distinguer la compréhension de la tâche et les difficultés d'accès à son énoncé. Les enseignants observeront les usages avant de décider quels documents adapter ensuite. Ils ne présentent pas le choix du support comme une dispense d'apprendre à lire, mais comme une aide pour participer aux activités prévues.","question":"Quel principe est retenu ?","explanation":"Le passage indique : « Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide. » Cela justifie la réponse : Multiplier les moyens d'accès à la consigne."},{"number":12,"points":15,"correct":"C","options":["Éviter toute interaction","Supprimer les activités libres","Favoriser la participation de chacun","Classer définitivement les participants"],"passage":"Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole.\n\nLes personnes peuvent commencer par des échanges courts puis rejoindre une discussion plus longue. Les animateurs proposent des thèmes proches du quotidien et demandent aux habitués de laisser un temps de réponse. Le centre veut éviter qu'un niveau élevé chez quelques participants rende les autres invisibles.","question":"Pourquoi varier les groupes ?","explanation":"Le passage indique : « Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole. » Cela justifie la réponse : Favoriser la participation de chacun."},{"number":13,"points":15,"correct":"A","options":["Identifier le statut des informations","Écrire sans vérifier","Éliminer toutes les questions","Publier uniquement des certitudes personnelles"],"passage":"Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester.\n\nLes groupes doivent indiquer d'où viennent leurs informations et conserver les documents consultés. Un enseignant les aide à voir quand une formulation affirme davantage que ce que la source permet. Les textes seront relus avant d'être montrés aux autres classes. Le projet souhaite donner une expérience concrète de publication, avec ses responsabilités. Les élèves pourront poser de nouvelles questions sans les présenter immédiatement comme des découvertes établies. Ils apprendront aussi à expliquer une incertitude plutôt qu'à la cacher pour rendre leur article plus impressionnant.","question":"Quel apprentissage est travaillé ?","explanation":"Le passage indique : « Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester. » Cela justifie la réponse : Identifier le statut des informations."},{"number":14,"points":15,"correct":"C","options":["Les participants choisissent leur diplôme","Les examens sont tirés au sort","Les acquis initiaux sont pris en compte","Le tarif dépend de la taille des classes"],"passage":"Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée.\n\nLes candidats apportent des exemples de tâches réalisées et décrivent les responsabilités qu'ils avaient réellement. L'exercice permet de vérifier certains points sans se fier uniquement au titre d'un ancien poste. Cette reconnaissance ne garantit pas une validation automatique : elle sert à rendre le parcours plus pertinent. Les participants savent ainsi pourquoi certaines séances leur sont proposées et pourquoi d'autres ne doivent pas nécessairement être suivies une seconde fois.","question":"Pourquoi la durée peut-elle varier ?","explanation":"Le passage indique : « Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée. » Cela justifie la réponse : Les acquis initiaux sont pris en compte."},{"number":15,"points":15,"correct":"C","options":["Distribuer des notes secrètes","Éviter toute correction","Apprendre à partir des erreurs","Remplacer définitivement l'évaluation"],"passage":"Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation.\n\nLe retour porte sur des éléments précis du raisonnement et sur les moyens de progresser. Les élèves peuvent poser une question avant de reprendre le document. L'enseignant souhaite que la note finale ne soit pas la première information reçue sur la qualité de leur démarche. Il prévoit aussi un temps pour comparer les deux versions et identifier les changements utiles. Ce travail n'efface pas les exigences de l'évaluation ; il rend plus visible ce qui peut être appris entre une tentative initiale et une production plus aboutie.","question":"À quoi sert le premier essai ?","explanation":"Le passage indique : « Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation. » Cela justifie la réponse : Apprendre à partir des erreurs."},{"number":16,"points":15,"correct":"D","options":["Recopier une publicité sans commentaire","Évaluer le salaire des visiteurs","Donner uniquement une impression avant la visite","Confronter une représentation à l'expérience"],"passage":"La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles.\n\nCertains découvrent des tâches peu visibles pendant une simple présentation du métier. Les responsables de l'entreprise répondent aux questions, mais ne corrigent pas toutes les impressions à leur place. L'école souhaite que les jeunes apprennent à formuler un constat et à l'appuyer sur une situation concrète, plutôt qu'à reproduire uniquement les éléments les plus valorisants d'une brochure de recrutement ou d'une visite préparée pour eux.","question":"Quelle démarche est demandée ?","explanation":"Le passage indique : « La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles. » Cela justifie la réponse : Confronter une représentation à l'expérience."},{"number":17,"points":15,"correct":"A","options":["Une barrière matérielle à la formation","Le manque de places de parking","Le nombre de devoirs","La durée du trimestre"],"passage":"Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours.\n\nLes étudiants peuvent poser des questions sans supposer qu'ils connaissent déjà le modèle. La formation ne veut pas évaluer une différence d'équipement familial à la place de la compétence travaillée. Les responsables suivront les demandes de prêt afin de prévoir un stock suffisant. Ils souhaitent que les personnes découvrent ce droit assez tôt pour ne pas abandonner une inscription simplement parce qu'elles pensent devoir acheter immédiatement du matériel supplémentaire.","question":"Quel problème cherche-t-on à réduire ?","explanation":"Le passage indique : « Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours. » Cela justifie la réponse : Une barrière matérielle à la formation."},{"number":18,"points":15,"correct":"B","options":["La suppression de la cour","Différentes façons de vivre la pause","Une obligation de rester en classe","Un examen pendant la récréation"],"passage":"Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves.\n\nLes élèves ont participé au choix des sièges et des règles d'usage. Certaines personnes y lisent, d'autres préfèrent simplement s'asseoir quelques minutes. L'établissement souhaite reconnaître des besoins différents pendant le même temps de pause. Le bilan portera sur la manière dont les espaces se complètent, plutôt que sur une compétition entre ceux qui choisissent de jouer dehors et ceux qui recherchent un environnement plus calme.","question":"Quel choix est offert ?","explanation":"Le passage indique : « Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves. » Cela justifie la réponse : Différentes façons de vivre la pause."},{"number":19,"points":15,"correct":"A","options":["Vérifier le contexte de l'image","Se fier uniquement à sa première impression","Ignorer la date de publication","Compter les couleurs"],"passage":"Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer.\n\nLes animateurs montrent comment une même image peut circuler avec des commentaires différents. Les participants essaient ensuite la démarche sur des exemples préparés pour l'atelier. Ils ne cherchent pas à démontrer que toute photographie serait fausse, mais à comprendre ce qui permet de lui attribuer un sens précis.","question":"Quelle précaution est enseignée ?","explanation":"Le passage indique : « Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer. » Cela justifie la réponse : Vérifier le contexte de l'image."},{"number":20,"points":21,"correct":"D","options":["Éviter tout travail personnel","Obtenir immédiatement tous les diplômes","Interdire une poursuite d'études","Commencer progressivement sans perdre ses acquis"],"passage":"Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. Le centre précise les étapes suivantes et les conditions de reprise dès le début. Les personnes peuvent ainsi décider si elles souhaitent poursuivre après avoir découvert le rythme et le travail demandé. L'objectif est de proposer une première expérience suffisamment complète pour être utile, sans transformer une hésitation initiale en échec. Les acquis seront décrits dans un document conservé par l'apprenant.","question":"Que permet ce dispositif ?","explanation":"Le passage indique : « Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. » Cela justifie la réponse : Commencer progressivement sans perdre ses acquis."},{"number":21,"points":21,"correct":"D","options":["Toutes les questions sont inutiles","Les élèves comprennent toujours les consignes","La répétition prouve nécessairement un refus d'apprendre","La clarté de l'enseignement doit aussi être examinée"],"passage":"Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. Les formateurs regroupent les difficultés récurrentes et comparent la façon dont les consignes ont été présentées. Ils peuvent alors modifier un exemple ou prévoir une explication supplémentaire. Elle permet simplement de ne pas attribuer automatiquement une difficulté collective à des défauts individuels, alors qu'une même formulation a peut-être laissé plusieurs personnes dans l'incertitude.","question":"Quelle interprétation est ajoutée ?","explanation":"Le passage indique : « Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. » Cela justifie la réponse : La clarté de l'enseignement doit aussi être examinée."},{"number":22,"points":21,"correct":"D","options":["Isolement et contrôle permanent","Absence d'horaires et absence de contact","Cours uniquement en présence","Autonomie et accompagnement"],"passage":"Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. Les échanges avec le tuteur servent à préparer les étapes suivantes et à discuter des obstacles rencontrés. Les participants n'ont pas tous le même emploi du temps ni le même équipement. Le programme prévoit donc plusieurs possibilités de rendez-vous, sans laisser chacun seul face à une liste de vidéos.","question":"Quels éléments sont combinés ?","explanation":"Le passage indique : « Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. » Cela justifie la réponse : Autonomie et accompagnement."},{"number":23,"points":21,"correct":"C","options":["Imposer une langue unique au domicile","Classer les familles selon leurs revenus","Reconnaître des pratiques linguistiques diverses","Organiser un examen pour les parents"],"passage":"Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. Les enfants peuvent apporter une chanson, expliquer une expression ou raconter un usage quotidien. Les enseignants ne demandent pas aux parents de représenter toute une langue ou tout un pays. Ils souhaitent donner une place à des expériences présentes dans la classe, sans transformer l'activité en concours.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. » Cela justifie la réponse : Reconnaître des pratiques linguistiques diverses."},{"number":24,"points":21,"correct":"D","options":["Éviter toute mise en pratique","Commencer par un classement des participants","Apprendre toutes les commandes sans usage","Partir d'un besoin pour introduire les notions"],"passage":"Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. Les premiers essais peuvent être faits sans écrire toutes les lignes à partir de zéro. Les participants pourront modifier l'exemple et observer le résultat. Le centre souhaite que les nouvelles commandes deviennent des moyens d'agir et de comprendre, plutôt que des mots mémorisés sans lien avec un objectif identifiable.","question":"Quelle progression pédagogique est choisie ?","explanation":"Le passage indique : « Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. » Cela justifie la réponse : Partir d'un besoin pour introduire les notions."},{"number":25,"points":21,"correct":"B","options":["Le tuteur peut fournir une réponse après une première erreur, puis demander à l'élève d'en expliquer les étapes.","Le tuteur oriente le raisonnement et reconnaît les situations nécessitant l'aide du professeur, dans les cas difficiles.","Le tuteur peut organiser la progression des exercices si l'enseignant garde la responsabilité de l'évaluation finale.","Le tuteur peut présenter sa propre méthode puis demander au camarade de refaire l'exercice pour la vérifier."],"passage":"Une association propose un tutorat entre élèves. Les tuteurs apprennent à poser des questions plutôt qu'à fournir directement la réponse. Les élèves préparant une aide reçoivent quelques repères pour écouter et vérifier ce que leur camarade a déjà essayé. Ils doivent savoir quand demander l'intervention du professeur. Il donne à chacun un rôle précis et permet aussi de découvrir que comprendre un exercice et aider quelqu'un à le comprendre sont deux activités différentes. Un tuteur remarque une erreur de calcul, mais demande d'abord à son camarade quelle étape lui semble incertaine. Quand une notion n'est plus maîtrisée par aucun des deux, ils sollicitent l'enseignant.","question":"Quelle frontière distingue le tutorat décrit d'une substitution à l'enseignant ?","explanation":"B décrit un tutorat qui questionne l'élève et sollicite le professeur lorsque la notion dépasse les deux camarades. A et D font du tuteur le fournisseur de la solution; C lui confie une organisation de la progression que le passage n'attribue pas à ce rôle."},{"number":26,"points":21,"correct":"A","options":["Parce que le transfert dépend des acquis et des occasions de les utiliser, dans le contexte professionnel.","Parce qu'une réaction favorable pendant le cours permet d'estimer les acquis mais non la fréquence de leur usage.","Parce que l'application des compétences se mesure surtout lorsque le nouveau poste ressemble au métier antérieur.","Parce que les participants ayant attendu plusieurs mois avant d'appliquer un savoir le perdent nécessairement."],"passage":"Le centre compare la satisfaction immédiate et l'utilisation réelle des compétences quelques mois plus tard. Un cours apprécié peut avoir peu d'effet si les participants n'ont pas l'occasion de pratiquer. Les anciens participants seront invités à décrire une situation où ils ont utilisé la formation et une autre où ils n'ont pas réussi à la mobiliser. Ils souhaitent distinguer un apprentissage réel, une appréciation favorable et les conditions nécessaires pour que ces acquis servent ensuite dans le travail ou dans les démarches prévues. Deux anciens élèves déclarent la même satisfaction. L'un utilise régulièrement la méthode apprise; l'autre travaille dans un service où il n'a pas accès au matériel nécessaire. Le bilan sépare acquis, occasion d'appliquer et ressenti.","question":"Pourquoi une satisfaction identique ne permet-elle pas de conclure au même effet de la formation ?","explanation":"A associe acquis et occasions réelles d'application. B confond satisfaction et compétence, C restreint sans preuve les situations de transfert, D suppose une perte automatique des connaissances."},{"number":27,"points":21,"correct":"C","options":["Sur la démarche adoptée par la majorité des camarades, puisque son utilisation répétée facilite la vérification.","Sur le nombre d'étapes requis, à condition que les deux procédures donnent des réponses correctes.","Sur les exigences du problème et les qualités respectives de chaque démarche correctement justifiée, dans chaque situation.","Sur la méthode présentée en premier par l'enseignant, dont les contraintes de calcul seraient normalement mieux connues."],"passage":"Un professeur montre deux solutions correctes à un problème. Les élèves doivent expliquer leurs différences plutôt que deviner laquelle l'enseignant préfère. Le professeur garde un rôle de vérification et ne présente pas toutes les propositions comme correctes par principe. Il veut que les élèves justifient leurs choix à partir du problème, au lieu de chercher seulement un indice sur la réponse qu'ils pensent attendue dans la classe. Une procédure est plus courte mais demande davantage de calcul mental; l'autre comporte davantage d'étapes et reste plus facile à vérifier. Les élèves doivent comparer ces propriétés en fonction du problème, sans qu'une seule méthode soit attendue.","question":"Sur quoi l'élève doit-il fonder le choix entre les deux solutions ?","explanation":"C demande de confronter les propriétés des deux méthodes au problème. A privilégie la popularité, B la brièveté sans contexte, D infère une préférence du professeur."},{"number":28,"points":21,"correct":"A","options":["Conserver des fonctions complémentaires et ajuster leur disponibilité en fonction des usages observés, entre examens et semaines ordinaires.","Conserver le même nombre de places de groupe, puis répondre aux demandes d'espace calme par un changement d'horaires.","Donner la priorité aux livres fragiles en limitant la durée des réservations de salles de travail collectif.","Accorder temporairement presque tout l'espace aux demandes de silence durant les examens, puis revenir au plan initial."],"passage":"Une université transforme une partie de sa bibliothèque en salles de groupe. Elle conserve des zones silencieuses après consultation des étudiants. Les étudiants ont expliqué à quels moments ils travaillent seuls, en groupe ou avec un document fragile. Elle souhaite éviter qu'un changement présenté comme moderne efface une fonction encore importante. Le bilan examinera la disponibilité réelle des espaces, notamment pendant les périodes où les demandes de travail individuel augmentent fortement. Pendant les examens, les salles de groupe sont pleines mais les demandes d'espaces silencieux doublent. La direction vérifie les besoins selon les périodes plutôt que d'évaluer l'aménagement sur une seule semaine.","question":"Quel principe devrait guider la répartition de l'espace de la bibliothèque ?","explanation":"A répartit les usages complémentaires selon la fréquentation constatée. B fige l'espace, C traite un autre usage comme solution globale, D fait presque disparaître les salles de groupe sans examen des besoins simultanés."},{"number":29,"points":21,"correct":"C","options":["Des absences répétées peuvent révéler une difficulté pédagogique malgré les bonnes notes obtenues aux évaluations.","Un stagiaire qui réussit les exercices pourrait compenser ses absences à l'aide des supports sans aide logistique.","Parce que les absences observées correspondent ici à des contraintes d'accès malgré des acquis suffisants.","Les difficultés de garde rendent les évaluations moins fiables comme preuve des acquis du stagiaire."],"passage":"Des participants abandonnent une formation malgré de bons résultats. Les entretiens révèlent des difficultés de garde et de transport. Le centre modifie ses aides plutôt que simplifier automatiquement les contenus. Les responsables ont contacté les personnes parties avant la fin pour comprendre leur expérience. Plusieurs souhaitaient continuer et savaient réaliser les exercices demandés. Le centre propose donc des solutions d'organisation et des relais locaux avant de revoir le niveau pédagogique. Un stagiaire réussit les évaluations mais manque trois cours faute de garde d'enfant. Le centre lui propose un soutien logistique plutôt qu'un cours simplifié; il vérifie ensuite si la présence reprend.","question":"Pourquoi le centre agit-il d'abord sur l'organisation de la formation ?","explanation":"C relie les absences à des obstacles de garde ou de transport malgré des acquis satisfaisants. A imagine une difficulté pédagogique non montrée; B suppose que les supports suffisent à lever les contraintes; D remet sans preuve en cause la validité des évaluations."},{"number":30,"points":26,"correct":"C","options":["Une procédure identique à appliquer à toute erreur afin de rendre les réponses plus homogènes.","La certitude de réussir à la tentative suivante, dès lors que l'élève identifie l'étape incorrecte.","Une compréhension exploitable de l'erreur et une possibilité d'ajuster la prochaine démarche, lors d'une reprise.","Une manière de valoriser toute réponse pour maintenir l'envie de poursuivre sans modifier la démarche."],"passage":"Le droit à l'erreur est souvent invoqué en formation. Il suppose pourtant un retour permettant de comprendre et de reprendre. Sans cet accompagnement, répéter qu'on peut se tromper laisse l'apprenant face à une difficulté inchangée. Le formateur peut montrer comment analyser une tentative et préparer le prochain essai. La personne dispose alors d'éléments pour agir, au lieu d'être simplement rassurée sans savoir ce qu'elle pourrait modifier concrètement. Le retour doit rester précis et utilisable pour la prochaine tentative. Deux apprenants commettent la même erreur. Le premier reçoit seulement « ce n'est pas grave »; le second examine son étape fautive et essaie une autre démarche. Seul le second possède une indication pour la prochaine tentative.","question":"Qu'apporte le retour détaillé que la seule permission de se tromper ne fournit pas ?","explanation":"C ajoute une analyse permettant de corriger le raisonnement. A uniformise des erreurs différentes, B promet la réussite, D néglige l'ajustement concret."},{"number":31,"points":26,"correct":"B","options":["Que le suivi des réponses soit jugé moins précis lorsque l'élève explore de nouvelles méthodes de résolution.","Qu'un parcours centré sur des erreurs passées réduise l'expérience de situations nouvelles et le transfert des acquis.","Que l'enseignant donne plus de poids aux erreurs passées qu'aux évaluations réalisées pendant les nouvelles tâches.","Que les exercices adaptés au niveau du moment retardent la vérification de compétences qui resteraient identiques."],"passage":"Un programme personnalise les exercices à partir des réponses précédentes. Les enseignants souhaitent garder une vue sur les choix du logiciel. Une adaptation automatique peut être utile tout en enfermant un élève dans des tâches trop semblables à celles qu'il a déjà réalisées. Les enseignants conservent donc des possibilités de changer la proposition ou d'introduire une tâche moins familière. Après plusieurs réponses faibles en géométrie, un élève reçoit presque exclusivement des exercices similaires. Il réussit ensuite mieux, mais n'a plus d'occasion d'appliquer les notions dans une situation nouvelle; le professeur introduit des tâches différentes.","question":"Quel risque la modification du parcours vise-t-elle à limiter ?","explanation":"B identifie une adaptation qui enferme l'élève dans des tâches similaires, limitant le transfert. A/C/D décrivent d'autres problèmes possibles mais pas le manque d'exposition à des contextes nouveaux observé."},{"number":32,"points":26,"correct":"B","options":["Parce que les élèves les plus avancés doivent rester responsables de toutes les étapes du projet commun.","Parce qu'un bon projet peut masquer une participation inégale des membres, même quand la production finale est satisfaisante.","Parce que les rôles attribués au début suffisent à établir les compétences que chacun a réellement acquises.","Parce que la rotation des rôles peut rendre la qualité du travail moins stable d'une séance à la suivante."],"passage":"Une école développe des projets collectifs. Pour éviter que seuls les élèves déjà à l'aise prennent les décisions, les rôles tournent et les méthodes sont discutées. Travailler ensemble ne suffit pas spontanément à répartir les occasions d'apprendre. Chaque élève pourra expliquer sa contribution et les difficultés rencontrées dans le rôle occupé. Cette attention évite de considérer qu'un résultat collectif réussi prouve automatiquement que tous les membres ont eu les mêmes occasions de travailler. Le groupe rend un projet réussi, mais son porte-parole a dirigé tous les échanges et les autres n'ont jamais présenté de décision. La rotation donne à chacun une occasion identifiable de mener, vérifier ou expliquer.","question":"Pourquoi un résultat collectif satisfaisant ne suffit-il pas à évaluer l'apprentissage des membres ?","explanation":"B désigne le risque que le bon résultat masque l'inégalité de participation et des occasions d'apprentissage. A préconise de concentrer les tâches, C confond attribution initiale et contribution réelle, D suppose une instabilité des résultats due aux rotations que le passage ne constate pas."},{"number":33,"points":26,"correct":"C","options":["La maîtrise d'un geste professionnel devrait être appréciée à partir du dossier écrit, même lorsque la procédure peut être directement observée.","Le récit oral peut remplacer l'observation lorsque la candidate sait décrire la procédure mais rédige difficilement son dossier.","Assimiler une difficulté à décrire une expérience à une absence de savoir-faire pratique, dans le dossier présenté.","L'objectif principal serait d'uniformiser la rédaction des dossiers, afin que les évaluateurs comparent des présentations identiques."],"passage":"Un adulte utilise efficacement un outil au travail mais peine à l'expliquer dans un dossier de formation. Son accompagnateur distingue la compétence pratique et la capacité à la décrire. L'une ne prouve pas automatiquement l'autre. Des exemples concrets et une observation peuvent compléter le dossier. Le centre souhaite éviter qu'une difficulté de rédaction masque un savoir réel, tout en aidant la personne à présenter ses acquis de manière compréhensible pour un évaluateur extérieur. Une candidate démontre oralement une procédure qu'elle applique chaque jour mais peine à en produire une description écrite. Le centre ajoute une observation guidée et une aide à la rédaction avant de statuer sur les compétences.","question":"Quel biais l'accompagnement cherche-t-il à éviter ?","explanation":"C évite d'assimiler une difficulté de rédaction à l'absence de compétence pratique. A privilégie le dossier au geste observé, B substitue l'oral à l'observation complémentaire, D confond la standardisation documentaire avec l'évaluation réelle des acquis."},{"number":34,"points":26,"correct":"D","options":["L'ordre de publication des résultats et le moment auquel les établissements ont fermé leurs inscriptions.","Les ressources consacrées aux épreuves peuvent expliquer les écarts, mais ne règlent pas les différences de dénominateur.","Le nombre d'étudiants présents aux examens pourrait suffire à comparer les résultats si les abandons sont publiés séparément.","Le périmètre des étudiants comptabilisés, notamment ceux partis avant l'examen, afin de comparer les établissements."],"passage":"Un établissement publie son taux de réussite. Il précise aussi les caractéristiques des étudiants accueillis et les parcours interrompus. Sans ces informations, comparer deux taux pourrait confondre l'effet de l'enseignement avec les conditions de recrutement ou de vie des étudiants. Les responsables souhaitent une comparaison utile, sans transformer un indicateur simple en verdict sur toutes les dimensions d'un établissement. Deux écoles publient 85 % de réussite. Dans la première, le calcul exclut les nombreux étudiants partis avant l'examen; la seconde suit l'ensemble des inscrits. La comparaison brute négligerait cette différence de périmètre.","question":"Quelle information est indispensable pour interpréter les taux annoncés ?","explanation":"D exige de comparer les étudiants inclus dans les deux taux, notamment les départs antérieurs à l'examen. A concerne le calendrier; B les moyens; C conserve une comparaison entre seuls présents qui ne règle pas la différence de périmètre annoncée."},{"number":35,"points":26,"correct":"B","options":["En donnant plus d'indices lorsque les exercices deviennent familiers pour maintenir la sécurité des réponses.","En diminuant progressivement et en réapparaissant de façon ciblée lorsque la difficulté l'exige, en situation nouvelle.","En conservant le même niveau d'aide pour rendre les performances comparables d'une séance à l'autre.","En retirant les aides après la première réussite, quitte à reprendre l'exercice si un problème nouveau apparaît."],"passage":"Un atelier vise l'autonomie. Les formateurs donnent progressivement moins d'indices, sans supprimer brutalement leur soutien. L'autonomie n'est pas supposée présente dès l'entrée : elle se construit dans une relation dont l'intensité évolue. Les apprenants sont invités à demander un appui lorsqu'une difficulté nouvelle apparaît. Le centre ne considère pas cette demande comme un échec de l'autonomie, mais comme une ressource possible pour continuer à progresser. La formatrice retire d'abord les exemples guidés, puis propose une situation moins familière. Si l'apprenant bloque, elle lui offre une question ciblée sans reprendre tout le raisonnement à sa place.","question":"Comment l'aide contribue-t-elle ici au développement de l'autonomie ?","explanation":"B décrit un étayage progressif et réajustable selon la difficulté. A augmente l'aide quand elle devrait diminuer; C la fige; D confond une première réussite et l'autonomie face à une situation nouvelle."},{"number":36,"points":33,"correct":"B","options":["Le nombre de tablettes distribuées et les compétences numériques déclarées, supposées directement comparables entre familles.","Le matériel distribué et les conditions réelles d'apprentissage à domicile, y compris l'accès aux ressources numériques.","La disponibilité d'un appareil à l'école et l'obligation de poursuivre toutes les tâches à domicile en ligne.","Le temps consacré aux devoirs et le niveau scolaire, considérés indépendamment de l'accès à la connexion."],"passage":"Une école distribue des tablettes à tous les élèves et constate des usages très différents. Certains disposent chez eux d'un espace calme et d'un adulte disponible ; d'autres partagent une connexion fragile. L'égalité d'équipement ne garantit pas l'égalité des conditions d'apprentissage. Certaines familles doivent attendre qu'un appareil soit libre pour terminer un devoir, tandis que d'autres peuvent reprendre les consignes à tout moment. L'école va donc proposer un accès encadré après les cours et des supports utilisables sans connexion permanente. Les enseignants examineront aussi la charge demandée à la maison. Le matériel distribué reste un progrès, mais ses effets dépendent des situations dans lesquelles il est utilisé. Le projet doit être évalué à partir de ces usages réels, pas seulement du nombre de tablettes remises lors d'une première journée de lancement. À équipement identique, un devoir vidéo se charge sans difficulté chez certains élèves, tandis que d'autres doivent attendre une connexion partagée. L'école ajoute une possibilité hors ligne plutôt que conclure à une égalité d'apprentissage.","question":"Quelle différence faut-il distinguer lorsqu'on évalue la distribution des tablettes ?","explanation":"B distingue l'égalité du matériel des conditions réelles de son usage, connexion et soutien. A/C assimilent équipement à apprentissage; D écarte précisément l'environnement matériel qui explique les différences."},{"number":37,"points":33,"correct":"A","options":["La flexibilité des règles de parcours et l'accès à l'accompagnement, en cohérence avec la promesse faite.","La durée totale du cursus, en maintenant les échéances communes pour préserver la comparabilité de l'évaluation.","La quantité d'exercices proposés en ligne, afin que les étudiants puissent apprendre seuls malgré les interruptions.","La difficulté des évaluations, adaptée aux rythmes individuels mais sans modifier la disponibilité des accompagnateurs."],"passage":"Une formation promet de respecter le rythme de chacun. Mais son calendrier final reste rigide, et les aides disparaissent après une courte période. Les participants qui ont besoin de plus de temps sont alors les premiers exclus. Une personnalisation annoncée doit être cohérente avec l'organisation qui encadre réellement les parcours. Les responsables avaient surtout décrit les possibilités offertes par les supports, sans regarder les délais ni la disponibilité des accompagnateurs. Les personnes intéressées pourront ainsi choisir en connaissant les limites du programme. Le centre souhaite conserver des objectifs communs sans prétendre qu'un outil flexible rend toutes les contraintes sans importance. Les résultats seront étudiés avec les abandons et les reprises, afin de vérifier si la nouvelle organisation aide effectivement ceux qui avaient du mal à suivre le rythme prévu. Une participante termine les exercices numériques à son rythme mais manque la date finale commune après une période de garde familiale. Les responsables envisagent des échéances de rattrapage et des aides prolongées.","question":"Que doit modifier le centre pour que la personnalisation soit autre chose qu'une propriété des supports ?","explanation":"A demande d'accorder délais de parcours et disponibilité d'aide avec la personnalisation annoncée. B/C/D changent durée, quantité ou niveau sans traiter ensemble les échéances rigides et le soutien limité."},{"number":38,"points":33,"correct":"B","options":["La capacité de suivre les étapes lorsque le chapitre et la formule pertinente sont indiqués à l'avance.","Le repérage des conditions dans lesquelles la méthode répond au problème posé, avant son exécution correcte.","La possibilité de reconnaître plusieurs formules d'un même chapitre avant de les appliquer successivement.","L'habitude de vérifier le résultat obtenu après avoir exécuté la méthode déjà désignée dans la consigne."],"passage":"Apprendre une méthode ne signifie pas toujours savoir quand l'utiliser. Des élèves réussissent un exercice familier, puis échouent lorsque le même problème apparaît dans une présentation différente. Le professeur multiplie les contextes et fait discuter les choix. La maîtrise implique aussi de reconnaître les situations auxquelles un savoir peut répondre. Les exercices proposés ensuite changent de présentation et mélangent plusieurs notions. Les élèves doivent expliquer pourquoi ils en choisissent une plutôt qu'une autre. Le professeur observe les hésitations, car elles peuvent révéler un repère mal compris malgré une procédure bien mémorisée. Il ne cherche pas à multiplier les pièges. Il veut rendre possible un passage des tâches familières à celles où il faut d'abord identifier le problème. Les retours aideront chacun à reconnaître des indices pertinents et à vérifier une démarche, plutôt qu'à reproduire automatiquement un geste appris dans un ordre toujours identique. Un élève applique une formule lorsque le chapitre est annoncé, mais choisit la mauvaise procédure lorsque plusieurs notions sont mélangées. Le professeur fait justifier les indices qui orientent vers une méthode.","question":"Quelle capacité manque à l'élève qui sait exécuter la formule dans un exercice familier ?","explanation":"B porte sur l'identification des indices qui rendent une méthode pertinente dans un contexte nouveau. A décrit la compétence déjà acquise; C reste à l'intérieur d'un chapitre désigné; D concerne le contrôle après sélection et non la sélection."},{"number":39,"points":33,"correct":"A","options":["L'expérience devient une ressource lorsqu'on peut expliciter ses conditions de validité et la réviser face à une contrainte nouvelle.","Les méthodes anciennes doivent être conservées si le participant peut expliquer pourquoi elles fonctionnaient dans son précédent service.","Une correction ponctuelle montre que le nouveau critère est compris et permet de présumer une adaptation durable à d'autres cas.","L'analyse du parcours antérieur devient secondaire lorsqu'un apprenant moins expérimenté parvient à appliquer le critère nouveau."],"passage":"Un centre valorise l'expérience de ses apprenants adultes. Il ne considère pourtant pas que cette expérience suffit à répondre à toute question. Les échanges mettent parfois en évidence des habitudes efficaces dans un contexte et inadaptées dans un autre. Reconnaître un parcours permet d'en faire une ressource d'analyse, sans le transformer en vérité intangible. Les apprenants apportent des exemples et discutent des conditions dans lesquelles leurs solutions ont fonctionné. Le formateur introduit d'autres situations pour faire apparaître les points communs et les différences. Certains participants découvrent qu'ils possèdent des ressources utiles sans avoir encore les mots pour les décrire. D'autres doivent modifier un automatisme longtemps efficace dans leur ancien contexte. Le cours ne demande donc ni d'oublier son parcours ni de s'y enfermer. Il propose de le travailler avec d'autres repères, afin de préparer des décisions plus adaptées aux situations nouvelles rencontrées pendant la formation ou ensuite. Un professionnel explique une pratique qui fonctionnait dans son ancien service; une nouvelle situation introduit une contrainte absente auparavant. Le groupe identifie ce qui reste transférable et ce qu'il faut modifier au lieu de rejeter ou d'appliquer sans examen l'expérience passée. Pour une évaluation, deux professionnels expérimentés résolvent un incident familier selon leur ancienne procédure. Dans le nouveau cadre, la même procédure impose désormais un délai de contrôle supplémentaire. L'un explique pourquoi son automatisme ancien doit être interrompu à cette étape; l'autre répète correctement le geste ancien, mais ne vérifie pas les nouvelles contraintes. Le formateur ne leur attribue pas des compétences générales différentes sur la seule base de cette observation. Il demande plutôt que chacun nomme ce qui reste pertinent, la condition nouvelle qui change le choix, puis un critère permettant de vérifier l'adaptation. Un troisième participant, moins expérimenté, réussit également en mobilisant ce critère après avoir écouté les deux raisonnements. Le centre précise qu'un bon parcours antérieur n'autorise pas à ignorer le contexte, et qu'une correction ponctuelle ne démontre pas, sans nouvel essai, une maîtrise transférable dans toute situation.","question":"Quelle conclusion pédagogique est la plus solidement appuyée par l'évaluation décrite ?","explanation":"A valorise l'expérience à condition de vérifier où elle reste valable et ce qu'une contrainte nouvelle impose de modifier. B conserve un automatisme sans vérifier le nouveau contexte, C extrapole d'un seul cas à la durée, D écarte l'analyse de l'expérience alors que le centre la traite comme ressource."}]}$paper_10$::jsonb);
do $check_and_activate$
declare rec record; n integer; oldq jsonb; newq jsonb; correct_index integer; changed_rows integer;
begin
 for rec in select p.id, p.content as new_content, old.content as old_content, s.changed
 from academy_tcf_reading.papers p
 join academy_tcf_reading.papers old on old.id=p.id and old.version='tcf-reading-2026-11-close-reading-v4'
 join cleanup_scope s on s.test_id=p.id
 where p.version='tcf-reading-2026-11-distractor-polish-v5'
 loop
   if (rec.new_content - 'questions' - 'version') <> (rec.old_content - 'questions' - 'version')
   then raise exception 'Non-question paper metadata modified %',rec.id; end if;
   if jsonb_array_length(rec.new_content->'questions')<>39 or (rec.new_content->>'maxPoints')::integer<>699 or (rec.new_content->>'seconds')::integer<>3600
   then raise exception 'Test structure modified %',rec.id; end if;
   for n in 1..39 loop
     newq=rec.new_content->'questions'->(n-1);
     oldq=rec.old_content->'questions'->(n-1);
     if not (n=any(rec.changed)) then
       if newq<>oldq then raise exception 'Untargeted question changed % Q%',rec.id,n; end if;
     else
       if (newq - 'options' - 'explanation') <> (oldq - 'options' - 'explanation')
       then raise exception 'Passage, stem, key, scoring, or extra metadata changed % Q%',rec.id,n; end if;
       correct_index=case newq->>'correct' when 'A' then 0 when 'B' then 1 when 'C' then 2 when 'D' then 3 else -1 end;
       if correct_index<0 or newq->'options'->>correct_index <> oldq->'options'->>correct_index
       then raise exception 'Correct answer changed % Q%',rec.id,n; end if;
     end if;
   end loop;
 end loop;
 update academy_tcf_reading.published_papers set version='tcf-reading-2026-11-distractor-polish-v5'
 where test_id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10') and version='tcf-reading-2026-11-close-reading-v4';
 get diagnostics changed_rows=row_count;
 if changed_rows<>4 then raise exception 'Expected 4 pointer updates, got %',changed_rows; end if;
end $check_and_activate$;
do $postcheck$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Catalog was modified'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10') and version='tcf-reading-2026-11-distractor-polish-v5')<>4 then raise exception 'Target catalog not updated'; end if;
 if exists((select test_id,version from cleanup_other_pointers except select test_id,version from academy_tcf_reading.published_papers)
 union all (select test_id,version from academy_tcf_reading.published_papers where test_id not in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10') except select test_id,version from cleanup_other_pointers)) then raise exception 'Other tests changed'; end if;
 if (select count(*) from academy_tcf_reading.papers)<>(select banks+4 from cleanup_before) then raise exception 'Historical bank row count changed'; end if;
 if (select md5(coalesce(string_agg(to_jsonb(p)::text,'' order by id,version),'')) from academy_tcf_reading.papers p where not (id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10') and version='tcf-reading-2026-11-distractor-polish-v5'))<>(select banks_digest from cleanup_before) then raise exception 'Historical bank data changed'; end if;
 if (select count(*) from academy_tcf_reading.attempts)<>(select attempts from cleanup_before) or
 (select md5(coalesce(string_agg(to_jsonb(a)::text,'' order by id),'')) from academy_tcf_reading.attempts a)<>(select attempts_digest from cleanup_before) then raise exception 'Student attempts changed'; end if;
end $postcheck$;
commit;